// ARQUIVO FONTE: 02_hepatologia_hda.js
// ==============================================================================

/**
 * ==============================================================================
 * MÓDULO 02: HEPATOLOGIA CLÍNICA E HEMORRAGIA DIGESTIVA ALTA (HDA)
 * ==============================================================================
 * Diretrizes Clínicas Oficiais:
 *  - AASLD / EASL Guidelines for Management of Portal Hypertension and Variceal Bleeding
 *  - Sociedade Brasileira de Hepatologia (SBH)
 *
 * PILARES CLÍNICOS DETERMINÍSTICOS:
 *  1. Escore MELD / MELD-Na (Model for End-Stage Liver Disease) e Child-Pugh:
 *     - Classificação de gravidade e ajuste posológico.
 *  2. Protocolo Ágil de Manejo de HDA Varicosa:
 *     - IBP IV Contínuo (Esomeprazol ou Pantoprazol: 80 mg bolus seguido de 8 mg/h contínuo).
 *     - Fármacos vasoativos: Terlipressina (2 mg IV bolus 4/4h inicial) ou Octreotide (50 mcg bolus + 50 mcg/h).
 *     - Profilaxia de PBE: Ceftriaxona 1g IV 1x/dia por 7 dias (máx).
 *     - Restrição volêmica (alvo PAS 90-100 mmHg; HR < 100).
 *     - Gatilhos transfusionais (alvo Hb 7-8 g/dL).
 */

const HepatologiaHdaService = (function() {

  function calcularChildPugh(bilirrubina, albumina, inr, ascite, encefalopatia) {
    let pontos = 0;
    
    // Bilirrubina (mg/dL)
    if (bilirrubina < 2.0) pontos += 1;
    else if (bilirrubina <= 3.0) pontos += 2;
    else pontos += 3;

    // Albumina (g/dL)
    if (albumina > 3.5) pontos += 1;
    else if (albumina >= 2.8) pontos += 2;
    else pontos += 3;

    // INR
    if (inr < 1.7) pontos += 1;
    else if (inr <= 2.2) pontos += 2;
    else pontos += 3;

    // Ascite (0=ausente, 1=leve/controlada, 2=moderada/tensa)
    if (ascite === 0) pontos += 1;
    else if (ascite === 1) pontos += 2;
    else pontos += 3;

    // Encefalopatia (0=ausente, 1=grau 1-2, 2=grau 3-4)
    if (encefalopatia === 0) pontos += 1;
    else if (encefalopatia === 1) pontos += 2;
    else pontos += 3;

    let classe = '';
    let sobrevida1ano = '';
    let sobrevida2anos = '';
    if (pontos <= 6) { classe = 'A'; sobrevida1ano = '100%'; sobrevida2anos = '85%'; }
    else if (pontos <= 9) { classe = 'B'; sobrevida1ano = '80%'; sobrevida2anos = '60%'; }
    else { classe = 'C'; sobrevida1ano = '45%'; sobrevida2anos = '35%'; }

    return { pontos, classe, sobrevida1ano, sobrevida2anos };
  }

  function calcularMeldNa(bilirrubina, inr, creatinina, sodio, dialise) {
    // Limits
    let cr = Math.max(1.0, creatinina);
    if (cr > 4.0 || dialise) cr = 4.0;
    
    let bil = Math.max(1.0, bilirrubina);
    let myInr = Math.max(1.0, inr);
    
    // Original MELD (UNOS formula)
    let meldOriginal = (3.78 * Math.log(bil)) + (11.2 * Math.log(myInr)) + (9.57 * Math.log(cr)) + 6.43;
    meldOriginal = Math.round(meldOriginal);
    
    if (meldOriginal < 11) {
        return { meldOriginal: meldOriginal, meldNa: meldOriginal };
    }

    let na = sodio;
    if (na < 125) na = 125;
    if (na > 137) na = 137;

    // MELD-Na formula
    let meldNa = meldOriginal - na - (0.025 * meldOriginal * (140 - na)) + 140;
    meldNa = Math.round(meldNa);

    return { meldOriginal, meldNa };
  }

  function manejarHdaVaricosa(peso, estabilidadeHemodinamica, contraindicacaoTerlipressina) {
    let t = [];
    
    t.push("💊 *Protocolo de HDA Varicosa (Hemorragia Digestiva Alta)*");
    t.push("━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━");
    
    // Ressuscitação e Metas
    t.push("💧 *1. Ressuscitação e Metas Hemodinâmicas:*");
    if (estabilidadeHemodinamica === false) {
       t.push(" • Acesso venoso duplo e calibroso. Iniciar ressuscitação volêmica cuidadosa.");
    }
    t.push(" • **Restrição de Cristaloides:** Evitar sobrecarga (risco de rebote de hipertensão portal). Alvo de PAS 90-100 mmHg.");
    t.push(" • **Transfusão Restritiva:** Transfundir CHAD apenas se Hb < 7 g/dL (alvo Hb 7 a 8 g/dL).");
    t.push("");

    // Fármaco Vasoativo
    t.push("🩸 *2. Droga Vasoativa (Iniciar IMEDIATAMENTE, antes da EDA):*");
    if (!contraindicacaoTerlipressina) {
       let doseTerli = (peso && peso < 50) ? "1 mg" : "2 mg";
       t.push(` • **Terlipressina:** ${doseTerli} IV em bolus a cada 4 horas (primeiras 24-48h).`);
       t.push("   ↳ _Alerta:_ Monitorar isquemia miocárdica/periférica e hiponatremia.");
    } else {
       t.push(" • **Octreotide:** 50 mcg IV em bolus, seguido de infusão contínua de 50 mcg/h.");
       t.push("   ↳ _(Indicado devido à contraindicação ou indisponibilidade de Terlipressina)_");
    }
    t.push("");

    // Profilaxia Infecciosa
    t.push("🦠 *3. Profilaxia para PBE (Peritonite Bacteriana Espontânea):*");
    t.push(" • **Ceftriaxona:** 1g IV a cada 24 horas (máx 7 dias).");
    t.push("   ↳ _Obrigatório em todo cirrótico com sangramento TGI, reduz mortalidade e ressangramento._");
    t.push("");

    // IBP
    t.push("💊 *4. Supressão Ácida (IBP):*");
    t.push(" • **Pantoprazol ou Esomeprazol:** 80 mg IV em bolus (2 ampolas).");
    t.push(" • Seguida de infusão contínua de 8 mg/h por 72h (ou 40 mg IV de 12/12h se infusão não disponível).");
    t.push("");

    // EDA
    t.push("🔬 *5. Endoscopia Digestiva Alta (EDA):*");
    t.push(" • Deve ser realizada em **< 12 horas** da admissão.");
    t.push(" • Considerar Eritromicina 250mg IV 30-120 min antes para esvaziamento gástrico (se disponível).");

    return t.join("\n");
  }

  function avaliarHepatopatia(params) {
    let p = params || {};
    let t = [];
    
    if (p.bilirrubina !== undefined && p.albumina !== undefined && p.inr !== undefined && p.ascite !== undefined && p.encefalopatia !== undefined) {
      const child = calcularChildPugh(p.bilirrubina, p.albumina, p.inr, p.ascite, p.encefalopatia);
      t.push(`📊 *Escore de Child-Pugh:* ${child.pontos} pontos (Classe ${child.classe})`);
      t.push(` • Sobrevida estimada: ${child.sobrevida1ano} (1 ano) / ${child.sobrevida2anos} (2 anos).`);
      
      if (child.classe === 'C') {
         t.push(" ⚠️ *Atenção:* Insuficiência hepática grave. Ajustar rigorosamente doses de medicações de metabolismo hepático.");
      }
      t.push("");
    }

    if (p.bilirrubina !== undefined && p.inr !== undefined && p.creatinina !== undefined && p.sodio !== undefined) {
      const meld = calcularMeldNa(p.bilirrubina, p.inr, p.creatinina, p.sodio, p.dialise || false);
      t.push(`📈 *Escore MELD-Na:* ${meld.meldNa}`);
      t.push(` • MELD Original: ${meld.meldOriginal}`);
      t.push(` • Reflete a mortalidade em 3 meses e indica prioridade para transplante hepático.`);
      t.push("");
    }

    if (p.hda) {
      t.push(manejarHdaVaricosa(p.peso || 70, p.estabilidadeHemodinamica, p.contraindicacaoTerlipressina));
    }

    return t.join("\n").trim();
  }

  return {
    calcularChildPugh: calcularChildPugh,
    calcularMeldNa: calcularMeldNa,
    manejarHdaVaricosa: manejarHdaVaricosa,
    avaliarHepatopatia: avaliarHepatopatia
  };

})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = HepatologiaHdaService;
  module.exports.HepatologiaHdaService = HepatologiaHdaService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_infectologia_neutropenia.js
// ==============================================================================

/**
 * Módulo de Infectologia: Manejo de Neutropenia Febril Oncológica
 * Motor determinístico baseado nas diretrizes MASCC, CISNE e IDSA.
 */

var InfectologiaNeutropeniaService = (function() {
    'use strict';

    function calcularMASCC(fatores) {
        // fatores: { cargaSintomas: 'leve'|'moderada'|'grave', semHipotensao: bool, semDpoc: bool, tumorSolidoOuHematoSemFungo: bool, semDesidratacao: bool, ambulatorial: bool, idadeMenor60: bool }
        var score = 0;
        
        if (fatores.cargaSintomas === 'leve' || fatores.cargaSintomas === 'assintomatico') score += 5;
        else if (fatores.cargaSintomas === 'moderada') score += 3;
        
        if (fatores.semHipotensao) score += 5;
        if (fatores.semDpoc) score += 4;
        if (fatores.tumorSolidoOuHematoSemFungo) score += 4;
        if (fatores.semDesidratacao) score += 3;
        if (fatores.ambulatorial) score += 3; // Início da febre em ambiente ambulatorial
        if (fatores.idadeMenor60) score += 2;
        
        var risco = score >= 21 ? 'Baixo Risco' : 'Alto Risco';
        var conduta = score >= 21 ? 'Elegível para tratamento ambulatorial seguro (Ciprofloxacino + Amoxicilina/Clavulanato) se reavaliação garantida.' : 'Internação hospitalar IMEDIATA requerida (Antibioticoterapia IV empírica).';
        
        return {
            escore: score,
            risco: risco,
            conduta: conduta
        };
    }

    
    function calcularCISNE(fatores) {
        // fatores: { ecogMaiorIgual2: bool, dpoc: bool, doencaCardiovascular: bool, mucosite: bool, monocitosMenor200: bool, hiperglicemiaEstresse: bool }
        var score = 0;
        
        if (fatores.ecogMaiorIgual2) score += 2;
        if (fatores.dpoc) score += 1;
        if (fatores.doencaCardiovascular) score += 1;
        if (fatores.mucosite) score += 1; // NCI CTCAE >= grade 2
        if (fatores.monocitosMenor200) score += 1;
        if (fatores.hiperglicemiaEstresse) score += 2;
        
        var risco = "";
        var complicacoes = "";
        
        if (score === 0) {
            risco = "Baixo Risco (CISNE)";
            complicacoes = "~1.1%";
        } else if (score >= 1 && score <= 2) {
            risco = "Risco Intermediário (CISNE)";
            complicacoes = "~6.2%";
        } else {
            risco = "Alto Risco (CISNE)";
            complicacoes = "~36%";
        }
        
        return {
            escore: score,
            risco: risco,
            complicacoes: complicacoes
        };
    }

    function protocoloAntibiotico(fatores) {
        // fatores: { instabilidade: bool, suspeitaCateter: bool, mrsa: bool, alergiaPenicilina: 'nao'|'leve'|'grave', diasFebre: number }
        var recomendacao = [];
        var bloqueios = [];
        var atbBase = "";

        if (fatores.alergiaPenicilina === 'grave') {
            atbBase = "Aztreonam 2g IV 8/8h + Vancomicina";
        } else {
            atbBase = "Cefepime 2g IV 8/8h OU Piperacilina-Tazobactam 4.5g IV 6/6h (terapia anti-pseudomonas)";
        }
        
        recomendacao.push("1ª Linha: " + atbBase);
        
        if (fatores.instabilidade || fatores.suspeitaCateter || fatores.mrsa) {
            recomendacao.push("Adicionar COBERTURA GRAM-POSITIVA (MRSA): Vancomicina 15-20 mg/kg IV 12/12h.");
            if (fatores.instabilidade) {
                recomendacao.push("ALERTA DE CHOQUE: Iniciar antibioticoterapia na 1ª hora (Golden Hour) + Ressuscitação Volêmica.");
            }
        }
        
        if (fatores.diasFebre >= 4 && fatores.diasFebre <= 7) {
            recomendacao.push("FEBRE REFRATÁRIA (> 4-7 dias): Forte indicação de terapia antifúngica empírica com Echinocandina (ex: Anidulafungina ou Caspofungina) ou Anfotericina B Lipossomal.");
        }
        
        return {
            recomendacoes: recomendacao,
            bloqueios: bloqueios
        };
    }

    function avaliarPaciente(params) {
        var mascc = calcularMASCC(params.mascc || {});
        var cisne = params.cisne ? calcularCISNE(params.cisne) : null;
        var atb = protocoloAntibiotico(params.clinica || {});
        
        var alertas = [];
        if (mascc.risco === 'Alto Risco') {
            alertas.push("ISOLAMENTO PROTETOR: Manter paciente em quarto privativo, higiene rigorosa das mãos.");
        }
        
        return {
            mascc: mascc,
            cisne: cisne,
            antibioticoterapia: atb,
            alertas: alertas
        };
    }

    return {
        calcularMASCC: calcularMASCC,
        calcularCISNE: calcularCISNE,
        protocoloAntibiotico: protocoloAntibiotico,
        avaliarPaciente: avaliarPaciente
    };
})();

if (typeof module !== 'undefined' && module.exports) {
    module.exports = InfectologiaNeutropeniaService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_mecanica_pulmonar_sdra.js
// ==============================================================================

/**
 * Módulo de Mecânica Pulmonar e Ventilação Protetora na SDRA (ARDSNet)
 * Motor determinístico para cálculos de ventilação mecânica beira-leito.
 */

var MecanicaPulmonarSdraService = (function() {
    'use strict';

    // --- PESO PREDITO (PBW) E VOLUME CORRENTE ---
    function calcularPesoPredito(alturaCm, sexo) {
        var alturaInches = alturaCm / 2.54;
        var pbw = 0;
        if (sexo.toLowerCase() === 'f') {
            pbw = 45.5 + 2.3 * (alturaInches - 60);
        } else {
            pbw = 50.0 + 2.3 * (alturaInches - 60);
        }
        return Math.max(0, Math.round(pbw * 10) / 10); // não permitir valor negativo
    }

    function calcularVolumeCorrente(pbw) {
        return {
            vt4: Math.round(pbw * 4),
            vt6: Math.round(pbw * 6),
            vt8: Math.round(pbw * 8)
        };
    }

    // --- MECÂNICA PULMONAR ---
    function avaliarMecanicaPulmonar(pplat, peep) {
        var deltaP = pplat - peep;
        var alertas = [];

        if (pplat > 30) {
            alertas.push("ALERTA CRÍTICO: Pressão de Platô > 30 cmH2O. Risco de barotrauma. Reduzir Volume Corrente.");
        }
        if (deltaP > 15) {
            alertas.push("ALERTA CRÍTICO: Driving Pressure (ΔP) > 15 cmH2O. Alta mortalidade. Ajustar Vt ou PEEP.");
        }

        return {
            drivingPressure: deltaP,
            pplatSegura: pplat <= 30,
            deltaPSegura: deltaP <= 15,
            alertas: alertas
        };
    }

    // --- CRITÉRIOS DE BERLIM (SDRA) E PRONAÇÃO ---
    function avaliarSdra(pao2, fio2, peep) {
        // fio2 em % (ex: 40 para 0.4 ou 40%)
        var fio2Decimal = fio2 > 1 ? fio2 / 100 : fio2;
        var relacaoPF = Math.round(pao2 / fio2Decimal);
        var classificacao = "Não preenche critérios graves de SDRA";
        var condutas = [];

        if (peep >= 5) {
            if (relacaoPF <= 100) {
                classificacao = "SDRA Grave (Critérios de Berlim)";
            } else if (relacaoPF <= 200) {
                classificacao = "SDRA Moderada (Critérios de Berlim)";
            } else if (relacaoPF <= 300) {
                classificacao = "SDRA Leve (Critérios de Berlim)";
            }
        } else {
            condutas.push("Reavaliar PEEP (mínimo 5 cmH2O para critérios de SDRA).");
        }

        if (relacaoPF < 150 && peep >= 10) { 
            condutas.push("INDICAÇÃO OPORTUNA: Posição Prona precoce (16h/dia) para P/F < 150 com PEEP >= 10.");
            condutas.push("INDICAÇÃO OPORTUNA: Bloqueio Neuromuscular (ex: Cisatracúrio) nas primeiras 48h.");
        } else if (relacaoPF < 150 && peep < 10 && peep >= 5) {
            condutas.push("CONSIDERAR: Aumentar PEEP e avaliar indicação de Prona se P/F mantiver < 150.");
        }

        return {
            pao2Fio2: relacaoPF,
            classificacao: classificacao,
            condutas: condutas
        };
    }

    function processarMecanica(params) {
        var pbw = calcularPesoPredito(params.alturaCm, params.sexo);
        var vt = calcularVolumeCorrente(pbw);
        var mecanica = avaliarMecanicaPulmonar(params.pplat, params.peep);
        var sdra = avaliarSdra(params.pao2, params.fio2, params.peep);

        return {
            pesoPreditoKg: pbw,
            volumeCorrenteAlvo: {
                vtProtetor4ml: vt.vt4,
                vtProtetor6ml: vt.vt6,
                vtPermissivo8ml: vt.vt8
            },
            mecanicaPulmonar: mecanica,
            gasometria: sdra
        };
    }

    // Exposição da API
    return {
        calcularPesoPredito: calcularPesoPredito,
        calcularVolumeCorrente: calcularVolumeCorrente,
        avaliarMecanicaPulmonar: avaliarMecanicaPulmonar,
        avaliarSdra: avaliarSdra,
        processarMecanica: processarMecanica
    };
})();

// Exportação para uso no Node.js/Testes
if (typeof module !== 'undefined' && module.exports) {
    module.exports = MecanicaPulmonarSdraService;
}


