// ARQUIVO FONTE: 02_transfusao_sanguinea.js
// ==============================================================================

/**
 * ==============================================================================
 * MÓDULO 02: PROTOCOLO AVANÇADO DE TRANSFUSÃO SANGUÍNEA E HEMOTERAPIA
 * ==============================================================================
 * Diretrizes Clínicas Oficiais e Ensaios Clínicos Seminais:
 *  - Ministério da Saúde do Brasil (Portaria de Consolidação nº 5/2017, Anexo IV)
 *  - Guia para o Uso de Hemocomponentes do Ministério da Saúde (2ª Edição)
 *  - Associação Brasileira de Hematologia, Hemoterapia e Terapia Celular (ABHH)
 *  - AABB Clinical Practice Guidelines on Red Blood Cell Transfusion (2023 Update)
 *  - Ensaios Seminais: TRICC, TRISS, FOCUS, REALITY, PROPPR, CRASH-2, WOMAN
 *  - International Society on Thrombosis and Haemostasis (ISTH) - Critérios de CIVD
 *
 * PILARES DETERMINÍSTICOS IMPLEMENTADOS:
 *  1. Gatilhos Transfusionais Restritivos vs Liberais para CHAD:
 *     - Estável / Clínico: Gatilho Hb < 7.0 g/dL (Alvo 7.0 - 9.0 g/dL)
 *     - Doença Coronariana Aguda / SCA / IAM: Gatilho Hb < 8.0 g/dL (Alvo 8.0 - 10.0 g/dL)
 *     - Neurocrítico / TCE Grave: Gatilho Hb < 7.0-8.0 g/dL (Alvo >= 8.0 - 9.0 g/dL)
 *     - Choque Séptico: Gatilho Hb < 7.0 g/dL (Alvo 7.0 - 9.0 g/dL)
 *     - Hemorragia Ativa com Instabilidade: Indicação imediata independente de Hb prévia
 *     - Cálculo ponderado de bolsas e incremento esperado (~1 g/dL por bolsa de 300 mL no adulto de 70 kg)
 *     - Alerta e prevenção de TACO (Transfusion-Associated Circulatory Overload)
 *  2. Protocolo de Transfusão Maciça (PTM / MTP - 1:1:1):
 *     - Escore ABC (Assessment of Blood Consumption: FC>=120, PAS<=90, trauma penetrante, FAST+)
 *     - Índice de Choque (FC/PAS >= 1.4 = choque catastrófico)
 *     - Pacote 1 (Imediato): 4-6 CHAD + 4-6 PFC + 1 Aférese de Plaquetas + Ácido Tranexâmico (TXA)
 *     - Regra de O Negativo em mulheres em idade fértil (<= 50 anos) vs O Positivo em homens/idosas
 *     - Janela crítica do TXA: 1g ataque + 1g infusão contínua em 8h se < 3h do trauma
 *     - Pacote 2 (Sequencial): Crioprecipitado + Gluconato de Cálcio 10% (combate à hipocalcemia por citrato)
 *     - Metas fisiológicas: Hb 7-9, Plaquetas > 50k (> 100k se TCE), Fibrinogênio > 150-200, RNI < 1.5, T > 35°C, pH > 7.20, Ca++ > 1.1 mmol/L
 *  3. Reposição Individual de Hemocomponentes & Coagulopatias:
 *     - Plasma Fresco Congelado (PFC): 10 a 15 mL/kg em sangramento ativo com RNI > 1.5 ou TTPA alargado
 *     - Concentrado de Plaquetas (CP): Gatilhos 10k (profilático), 20k (sepse/febre), 50k (sangramento/cirurgia), 100k (SNC/ocular)
 *     - Bloqueio sentinela de plaquetas em PTT e HIT (risco de trombose fatal)
 *     - Crioprecipitado: 1 UI a cada 5-10 kg (ou 10 UI) para Fibrinogênio < 150 mg/dL (< 200 em HPP/trauma)
 *     - Escore ISTH para CIVD Manifesta (Overt DIC) com suporte hemoterápico multimodal
 *  4. Diagnóstico e Manejo de Reações Transfusionais Agudas (RTA):
 *     - Reação Hemolítica Aguda (ABO), Anafilaxia, TACO, TRALI, RFNH, Alérgica Leve e Choque Séptico/Bacteriano
 * ==============================================================================
 */

var TransfusaoSanguineaService = (function() {
  'use strict';

  /**
   * Avalia gatilho transfusional determinístico para Concentrado de Hemácias (CHAD).
   * @param {Object} params
   * @returns {Object}
   */
  function avaliarGatilhoTransfusionalChad(params) {
    params = params || {};
    var peso = Math.max(30, Math.min(250, Number(params.peso) || 70));
    var sexo = String(params.sexo || 'M').toUpperCase() === 'F' ? 'F' : 'M';
    var hb = params.hb !== undefined && params.hb !== null ? Number(params.hb) : null;
    var ht = params.ht !== undefined && params.ht !== null ? Number(params.ht) : null;

    if (hb === null && ht !== null) {
      hb = Math.round((ht / 3) * 10) / 10;
    }

    var cenario = String(params.cenarioClinico || params.condicao || 'ESTAVEL_GERAL').toUpperCase();
    var sintomas = params.sintomasAnemia || false;
    var comorbidades = Array.isArray(params.comorbidades) ? params.comorbidades : [];
    var idade = Number(params.idade) || 50;

    // Detecção de risco de sobrecarga circulatória (TACO)
    var riscoTaco = params.riscoTaco === true || idade >= 65;
    for (var i = 0; i < comorbidades.length; i++) {
      var cNorm = String(comorbidades[i]).toUpperCase();
      if (cNorm.indexOf('ICC') >= 0 || cNorm.indexOf('CARDIACA') >= 0 || cNorm.indexOf('DRC') >= 0 || cNorm.indexOf('RENAL') >= 0) {
        riscoTaco = true;
      }
    }

    // Definição do limiar/gatilho baseado em diretrizes (TRICC, FOCUS, REALITY, AABB, MS)
    var gatilhoHb = 7.0;
    var hbAlvo = 8.0;
    var estrategia = 'RESTRITIVA';
    var justificativaGatilho = '';

    if (cenario.indexOf('HEMORRAGIA') >= 0 || cenario.indexOf('CHOQUE_HEMORRAGICO') >= 0 || cenario.indexOf('SANGRAMENTO_ATIVO_INSTAVEL') >= 0) {
      estrategia = 'RESSUSCITACAO_HEMORRAGICA';
      gatilhoHb = 10.0; // Não aguarda exames laboratoriais
      hbAlvo = 9.0;
      justificativaGatilho = 'Hemorragia aguda com instabilidade hemodinâmica. A indicação transfusional é CLÍNICA e IMEDIATA, não devendo aguardar dosagem laboratorial.';
    } else if (cenario.indexOf('CORONARI') >= 0 || cenario.indexOf('SCA') >= 0 || cenario.indexOf('IAM') >= 0 || cenario.indexOf('ISQUEMIA_MIOCARDICA') >= 0) {
      estrategia = 'LIBERAL_MODIFICADA';
      gatilhoHb = 8.0;
      hbAlvo = 9.0;
      justificativaGatilho = 'Síndrome Coronariana Aguda / Doença Coronariana Isquêmica ativa (estudos REALITY e FOCUS). Meta de manter Hb >= 8,0 g/dL para prevenir isquemia miocárdica.';
    } else if (cenario.indexOf('NEUROCRITICO') >= 0 || cenario.indexOf('TCE') >= 0 || cenario.indexOf('HIC') >= 0 || cenario.indexOf('AVC_AGUDO') >= 0) {
      estrategia = 'NEUROPROTECAO';
      gatilhoHb = 8.0;
      hbAlvo = 9.0;
      justificativaGatilho = 'Paciente neurocrítico com TCE grave ou risco de isquemia cerebral secundária. Recomenda-se manter Hb em torno de 8,0 a 9,0 g/dL.';
    } else if (cenario.indexOf('CHOQUE_SEPTICO') >= 0 || cenario.indexOf('SEPSE') >= 0) {
      estrategia = 'RESTRITIVA_SEPSE';
      gatilhoHb = 7.0;
      hbAlvo = 8.0;
      justificativaGatilho = 'Sepse / Choque Séptico (Diretrizes Surviving Sepsis Campaign 2021). Estratégia restritiva com gatilho Hb < 7,0 g/dL, reduzindo mortalidade e complicações pulmonares.';
    } else if (cenario.indexOf('ORTOPED') >= 0 || cenario.indexOf('POS_OP') >= 0) {
      if (riscoTaco || comorbidades.length > 0) {
        estrategia = 'LIBERAL_MODIFICADA';
        gatilhoHb = 8.0;
        hbAlvo = 8.5;
        justificativaGatilho = 'Pós-operatório cirúrgico com comorbidade cardiovascular associada. Gatilho seguro com Hb < 8,0 g/dL.';
      } else {
        estrategia = 'RESTRITIVA';
        gatilhoHb = 7.0;
        hbAlvo = 8.0;
        justificativaGatilho = 'Pós-operatório sem doença coronariana prévia. Estratégia restritiva segura (Hb < 7,0 g/dL).';
      }
    } else {
      estrategia = 'RESTRITIVA';
      gatilhoHb = 7.0;
      hbAlvo = 8.0;
      justificativaGatilho = 'Paciente clínico estável (TRICC Trial / Diretrizes AABB 2023). Estratégia restritiva com gatilho estrito de Hb < 7,0 g/dL.';
    }

    // Avaliação de sintomas graves de hipóxia tecidual mesmo com Hb limítrofe
    var sintomasAnemiaGraves = false;
    if (sintomas === true || (Array.isArray(sintomas) && sintomas.length > 0)) {
      sintomasAnemiaGraves = true;
    }

    var indicada = false;
    var urgencia = 'NAO_INDICADA';

    if (estrategia === 'RESSUSCITACAO_HEMORRAGICA') {
      indicada = true;
      urgencia = 'EMERGENCIA';
    } else if (hb !== null && hb < gatilhoHb) {
      indicada = true;
      urgencia = hb < 5.0 ? 'URGENTE' : 'ROTINA_SUPERVISIONADA';
    } else if (hb !== null && hb >= gatilhoHb && hb < (gatilhoHb + 1.0) && sintomasAnemiaGraves) {
      indicada = true;
      urgencia = 'ROTINA_SUPERVISIONADA';
      justificativaGatilho += ' Presença de sintomas clínicos de descompensação anêmica (ex: taquicardia desproporcional, angina, síncope ou hipotensão ortostática).';
    }

    // Cálculo do incremento esperado e bolsas
    // 1 bolsa de CHAD (~300 mL com Ht 60-70%) eleva ~1 g/dL de Hb em adulto de 70 kg
    var deltaHbPorBolsa = Math.round((1.0 * (70 / peso)) * 100) / 100;
    var bolsasRecomendadas = 0;

    if (indicada) {
      if (estrategia === 'RESSUSCITACAO_HEMORRAGICA') {
        bolsasRecomendadas = 2; // Início habitual antes do PTM pleno
      } else if (hb !== null) {
        var deficitHb = Math.max(0.5, hbAlvo - hb);
        bolsasRecomendadas = Math.max(1, Math.round(deficitHb / deltaHbPorBolsa));
        // Regra de ouro da segurança: no paciente estável, transfundir 1 bolsa de cada vez
        if (cenario.indexOf('ESTAVEL') >= 0 && hb >= 5.5) {
          bolsasRecomendadas = 1;
        }
      } else {
        bolsasRecomendadas = 1;
      }
    }

    var alertaTaco = null;
    var recomendacaoVelocidade = 'Infundir cada bolsa em 60 a 120 minutos (máximo de 4 horas por bolsa pelo risco de contaminação bacteriana).';

    if (idade >= 90) {
      alertaTaco = '🚨 PACIENTE NONAGENÁRIO (≥ 90 ANOS) - RISCO CRÍTICO DE TACO: Sobrecarga circulatória é a principal causa de óbito hemoterápico no paciente muito idoso. Transfundir estritamente UMA unidade por vez em velocidade lenta (3 a 4 horas). Administrar Furosemida 20 a 40 mg IV profilática antes ou entre as bolsas e monitorar ausculta respiratória e oximetria continuamente.';
      recomendacaoVelocidade = 'Infundir ultralentamente em 3 a 4 horas sob vigilância cardiorrespiratória estrita.';
    } else if (riscoTaco) {
      alertaTaco = '⚠️ ALTO RISCO DE SOBRECARGA CIRCULATÓRIA (TACO): Idade avançada, cardiopatia ou nefropatia prévia. Infundir em velocidade lenta (3 a 4 horas por unidade). Avaliar Furosemida 20 a 40 mg IV entre as bolsas e monitorar ausculta pulmonar e SpO2.';
      recomendacaoVelocidade = 'Infundir lentamente em 3 a 4 horas sob estrita vigilância de sinais de congestão (estertores, turgência jugular, dispneia).';
    }

    var alertas = [];
    var pesoInformado = params.peso !== undefined && params.peso !== null ? Number(params.peso) : null;
    if (pesoInformado !== null && pesoInformado > 0 && pesoInformado < 30) {
      alertas.unshift('⚠️ ALÍQUOTA PEDIÁTRICA/NEONATAL (< 30 kg): NUNCA prescrever bolsas inteiras de adulto (300 mL). Transfusão pediátrica deve ser prescrita em alíquotas de 10 a 15 mL/kg de CHAD (' + Math.round(pesoInformado * 10) + ' a ' + Math.round(pesoInformado * 15) + ' mL para ' + pesoInformado + ' kg) em bomba de infusão.');
    }
    if (pesoInformado !== null && pesoInformado > 150) {
      alertas.unshift('⚠️ OBESIDADE SEVERA (> 150 kg): O volume circulatório relativo é reduzido (~45-50 mL/kg vs 70 mL/kg). O risco de sobrecarga circulatória (TACO) é aumentado se houver cardiopatia associada.');
    }
    if (hb !== null && hb <= 4.0) {
      alertas.unshift('🚨 HEMOGLOBINA CRÍTICA EXTREMA (Hb ≤ 4.0 g/dL): Risco iminente de colapso circulatório anóxico e parada cardíaca. Transfusão de hemácias emergencial imediata e admissão em UTI.');
    }

    if (!indicada && hb !== null && hb >= gatilhoHb) {
      alertas.push('Estratégia restritiva mantida: Transfusão de hemácias NÃO indicada neste momento (Hb atual >= gatilho de ' + gatilhoHb.toFixed(1) + ' g/dL). Evita riscos de aloimunização, sobrecarga volêmica (TACO) e lesão pulmonar aguda (TRALI).');
      alertas.push('Reavaliar clinicamente e investigar a etiologia da anemia (deficiência de ferro, B12, folato ou perda crônica).');
    }

    if (indicada) {
      alertas.push('Doutrina PBM (Patient Blood Management): Transfundir UMA unidade por vez no paciente estável e dosar Hb de controle após 1-2h da infusão.');
      alertas.push('Coleta pré-transfusional obrigatória: Tipagem ABO/Rh, Pesquisa de Anticorpos Irregulares (PAI) e Prova de Compatibilidade Maior.');
    }

    return {
      indicada: indicada,
      urgencia: urgencia,
      estrategia: estrategia,
      hbInformada: hb,
      gatilhoHb: gatilhoHb,
      hbAlvo: hbAlvo,
      pesoKg: peso,
      sexo: sexo,
      deltaEsperadoPorBolsa: deltaHbPorBolsa,
      bolsasCalculadas: bolsasRecomendadas,
      justificativaGatilho: justificativaGatilho,
      riscoTaco: riscoTaco,
      alertaTaco: alertaTaco,
      recomendacaoVelocidade: recomendacaoVelocidade,
      alertas: alertas
    };
  }

  /**
   * Avalia escores e calcula pacotes determinísticos para o Protocolo de Transfusão Maciça (PTM).
   * @param {Object} params
   * @returns {Object}
   */
  function calcularProtocoloTransfusaoMaciça(params) {
    params = params || {};
    var peso = Math.max(30, Math.min(250, Number(params.peso) || 70));
    var idade = Number(params.idade) || 35;
    var sexo = String(params.sexo || 'M').toUpperCase() === 'F' ? 'F' : 'M';
    var fc = Number(params.fc) || 80;
    var pas = Number(params.pas) || 120;
    var traumaPenetrante = params.traumaPenetrante === true;
    var fastPositivo = params.fastPositivo === true;
    var sangramentoAtivo = params.sangramentoAtivo !== false;
    var tempoInicioSangramentoHoras = params.tempoInicioSangramentoHoras !== undefined ? Number(params.tempoInicioSangramentoHoras) : 1.0;

    // 1. Escore ABC (Assessment of Blood Consumption)
    // 4 parâmetros: FC >= 120, PAS <= 90, trauma penetrante, FAST positivo
    var abcPontos = 0;
    var abcCriterios = [];

    if (fc >= 120) {
      abcPontos += 1;
      abcCriterios.push('Taquicardia severa (FC >= 120 bpm: ' + fc + ' bpm)');
    }
    if (pas <= 90) {
      abcPontos += 1;
      abcCriterios.push('Hipotensão arterial sistólica (PAS <= 90 mmHg: ' + pas + ' mmHg)');
    }
    if (traumaPenetrante) {
      abcPontos += 1;
      abcCriterios.push('Mecanismo de trauma penetrante (alto risco de lesão vascular)');
    }
    if (fastPositivo) {
      abcPontos += 1;
      abcCriterios.push('Ultrassonografia beira-leito FAST positiva com líquido livre intra-abdominal/pélvico');
    }

    // 2. Índice de Choque (Shock Index = FC / PAS)
    var shockIndex = Math.round((fc / Math.max(1, pas)) * 100) / 100;
    var gravidadeChoque = 'NORMAL';
    var alertaShockIndex = 'Índice de choque normal (0,5 a 0,7). Sem evidência de colapso hemodinâmico.';

    if (shockIndex >= 1.4) {
      gravidadeChoque = 'CHOQUE_GRAVE_CATASTROFICO';
      alertaShockIndex = '🚨 ÍNDICE DE CHOQUE >= 1.4: Choque hemorrágico catastrófico com perda superior a 40-50% da volemia! Risco iminente de colapso circulatório.';
    } else if (shockIndex >= 1.0) {
      gravidadeChoque = 'CHOQUE_MODERADO';
      alertaShockIndex = '⚠️ ÍNDICE DE CHOQUE >= 1.0: Choque descompensado com perda volêmica importante (30-40%).';
    } else if (shockIndex >= 0.8) {
      gravidadeChoque = 'CHOQUE_COMPENSADO';
      alertaShockIndex = 'Índice de choque discretamente elevado (0,8 a 0,9). Alerta para sangramento oculto.';
    }

    // Critério formal de ativação do PTM: ABC >= 2 OU Shock Index >= 1.4 com sangramento OU sangramento maciço ativo
    var ativacaoPtm = (abcPontos >= 2) || (shockIndex >= 1.4 && sangramentoAtivo) || params.ativacaoManual === true;

    // Regra estrita de seleção de CHAD emergencial não-tipado
    var tipoChadEmergencia = 'O_POSITIVO';
    var justificativaTipoChad = '';

    if (sexo === 'F' && idade <= 50) {
      tipoChadEmergencia = 'O_NEGATIVO';
      justificativaTipoChad = 'MULHER EM IDADE FÉRTIL (<= 50 ANOS): Concentrado de Hemácias O NEGATIVO obrigatório até sair tipagem para prevenir aloimunização contra antígeno RhD e doença hemolítica perinatal em futuras gestações.';
    } else {
      tipoChadEmergencia = 'O_POSITIVO';
      justificativaTipoChad = 'HOMEM OU MULHER PÓS-MENOPAUSA (> 50 ANOS): CHAD O POSITIVO liberado imediatamente na emergência para preservação do estoque crítico de O Negativo do hemocentro.';
    }

    // Manejo de Ácido Tranexâmico (TXA - CRASH-2 e WOMAN)
    var indicacaoTxa = false;
    var prescricaoTxa = null;
    var alertaTxa = '';

    if (sangramentoAtivo) {
      if (tempoInicioSangramentoHoras <= 3.0) {
        indicacaoTxa = true;
        prescricaoTxa = {
          droga: 'Ácido Tranexâmico (TXA)',
          ataque: '1 g IV diluído em 100 mL de SF 0,9% infundido em 10 minutos',
          manutencao: '1 g IV diluído em 500 mL de SF 0,9% em infusão contínua por 8 horas',
          janelaTempo: tempoInicioSangramentoHoras.toFixed(1) + ' horas do trauma/sangramento',
          estudoReferencia: 'CRASH-2 / WOMAN Trial (redução de 20-30% de mortalidade por sangramento se < 3h)'
        };
        alertaTxa = 'Iniciar Ácido Tranexâmico IMEDIATAMENTE (dentro da janela salvadora de 3 horas).';
      } else {
        indicacaoTxa = false;
        alertaTxa = '⛔ JANELA TERAPÊUTICA DO ÁCIDO TRANEXÂMICO EXPIRADA (> 3 HORAS): Evidências demonstram que administrar TXA após 3 horas do sangramento aumenta a mortalidade por eventos trombóticos sem benefício hemostático.';
      }
    }

    // Pacotes Balanceados de Ressuscitação Hemostática (Damage Control Resuscitation 1:1:1)
    var pacote1 = {
      nome: 'Pacote 1 (Ressuscitação Imediata)',
      chad: {
        quantidade: 4,
        unidade: 'bolsas',
        tipoRecomendado: tipoChadEmergencia,
        volumeTotalAproxMl: 1200
      },
      pfc: {
        quantidade: 4,
        unidade: 'bolsas',
        tipoRecomendado: 'Plasma Fresco Congelado tipo AB (ou tipo A de baixo título)',
        volumeTotalAproxMl: 900
      },
      plaquetas: {
        quantidade: 1,
        unidade: 'pool de aférese',
        equivalencia: 'Equivalente a 5-6 unidades de concentrado de plaquetas randômico'
      },
      txa: prescricaoTxa
    };

    var pacote2 = {
      nome: 'Pacote 2 (Manutenção & Coagulopatia de Consumo)',
      chad: { quantidade: 4, unidade: 'bolsas' },
      pfc: { quantidade: 4, unidade: 'bolsas' },
      plaquetas: { quantidade: 1, unidade: 'pool de aférese' },
      crioprecipitado: {
        quantidade: 10,
        unidade: 'bolsas',
        indicacao: 'Reposição maciça de fibrinogênio para prevenir coagulopatia dilucional'
      },
      gluconatoCalcio: {
        droga: 'Gluconato de Cálcio 10%',
        posologia: '1 a 2 g IV lento (10 a 20 mL) a cada 4 unidades de hemocomponentes infundidas',
        justificativa: 'O citrato anticoagulante das bolsas quela o cálcio iônico sérico causando hipotensão refratária, arritmias e inibição da coagulação.'
      }
    };

    var metasFisiologicas = [
      { parametro: 'Hemoglobina (Hb)', alvo: '7,0 a 9,0 g/dL', conduta: 'Evitar hiperviscosidade ou hipóxia' },
      { parametro: 'Plaquetas', alvo: '> 50.000/mcL (> 100.000 se TCE/SNC)', conduta: 'Repor concentrado de plaquetas' },
      { parametro: 'Fibrinogênio', alvo: '> 150 a 200 mg/dL', conduta: 'Repor Crioprecipitado 10 UI se < 150-200' },
      { parametro: 'RNI / TAP', alvo: '< 1,5', conduta: 'Titular Plasma Fresco Congelado (PFC)' },
      { parametro: 'Temperatura Central', alvo: '> 35,0 ºC', conduta: 'Aquecedor rápido de fluidos e mantas térmicas' },
      { parametro: 'pH Arterial', alvo: '> 7,20 (Lactato em queda)', conduta: 'Restabelecer perfusão e debelar acidose' },
      { parametro: 'Cálcio Iônico', alvo: '> 1,1 mmol/L (> 4,5 mg/dL)', conduta: 'Gluconato de Cálcio 10% 1-2g a cada 4 bolsas' }
    ];

    var alertasCriticos = [];
    alertasCriticos.push(justificativaTipoChad);
    if (alertaTxa) alertasCriticos.push(alertaTxa);
    alertasCriticos.push('Tríade Letal do Trauma (Hipotermia + Acidose + Coagulopatia): Manter aquecimento ativo mandatória. A cada 1ºC de queda térmica, a função dos fatores de coagulação cai em 10%.');
    alertasCriticos.push('Vigilância de Hipercalemia: Em transfusões rápidas de múltiplas unidades de hemácias estocadas, monitorar ECG e K+ sérico.');

    return {
      ativacaoPtm: ativacaoPtm,
      abcPontos: abcPontos,
      abcCriterios: abcCriterios,
      shockIndex: shockIndex,
      gravidadeChoque: gravidadeChoque,
      alertaShockIndex: alertaShockIndex,
      tipoChadEmergencia: tipoChadEmergencia,
      pacote1: pacote1,
      pacote2: pacote2,
      txa: prescricaoTxa,
      metasFisiologicas: metasFisiologicas,
      alertasCriticos: alertasCriticos
    };
  }

  /**
   * Avalia necessidade e calcula dose determinística de Plasma Fresco Congelado (PFC).
   * @param {Object} params
   * @returns {Object}
   */
  function calcularReposicaoPfc(params) {
    params = params || {};
    var peso = Math.max(30, Math.min(250, Number(params.peso) || 70));
    var rni = params.rni !== undefined && params.rni !== null ? Number(params.rni) : null;
    var ttpaRatio = params.ttpaRatio !== undefined && params.ttpaRatio !== null ? Number(params.ttpaRatio) : null;
    var sangramentoAtivo = params.sangramentoAtivo === true;
    var procedimentoInvasivo = params.procedimentoInvasivo === true;
    var motivoClinico = String(params.motivo || '').toUpperCase();

    var alteracaoCoagulacao = (rni !== null && rni > 1.5) || (ttpaRatio !== null && ttpaRatio > 1.5);
    var indicada = false;
    var justificativa = '';

    if (alteracaoCoagulacao && (sangramentoAtivo || procedimentoInvasivo)) {
      indicada = true;
      justificativa = 'Coagulopatia documentada (RNI > 1,5 ou TTPa alargado > 1,5x) associada a sangramento ativo ou necessidade de procedimento invasivo de médio/alto porte.';
    } else if (motivoClinico.indexOf('CIVD') >= 0 || motivoClinico.indexOf('PTM') >= 0 || motivoClinico.indexOf('TRANSFUSAO_MACICA') >= 0) {
      indicada = true;
      justificativa = 'Indicação no contexto de Transfusão Maciça ou CIVD com sangramento associado.';
    } else if (alteracaoCoagulacao && !sangramentoAtivo && !procedimentoInvasivo) {
      indicada = false;
      justificativa = 'RNI discretamente alterado sem sangramento ativo nem procedimento cirúrgico programado. Transfusão de PFC NÃO indicada profilaticamente pelo risco de TACO e TRALI.';
    } else {
      indicada = false;
      justificativa = 'Ausência de coagulopatia clinicamente relevante que justifique uso de PFC.';
    }

    // Dose padrão internacional: 10 a 15 mL/kg de peso
    var volumeMlMin = Math.round(peso * 10);
    var volumeMlMax = Math.round(peso * 15);
    var volumeMlPadrao = Math.round(peso * 12);
    // Cada bolsa de PFC contém em média 200 a 250 mL
    var bolsasRecomendadas = Math.max(2, Math.ceil(volumeMlPadrao / 225));

    var alertas = [];
    if (!indicada) {
      alertas.push('Contraindicação relativa: PFC NÃO deve ser usado como expansor plasmático volêmico nem apenas para normalizar RNI < 1,5.');
    } else {
      alertas.push('Velocidade de infusão: 30 a 60 minutos por bolsa. Monitorar sinais de sobrecarga volêmica.');
      alertas.push('Compatibilidade ABO obrigatória: O PFC deve ser compatível com os eritrócitos do receptor (não requer prova cruzada de hemácias).');
      alertas.push('Incremento esperado: Esta dose eleva os fatores de coagulação séricos em aproximadamente 15% a 25%.');
    }

    return {
      indicada: indicada,
      rni: rni,
      ttpaRatio: ttpaRatio,
      pesoKg: peso,
      justificativa: justificativa,
      dosePorKg: '10 a 15 mL/kg',
      volumeTotalRecomendadoMl: volumeMlPadrao,
      intervaloVolumeMl: volumeMlMin + ' a ' + volumeMlMax + ' mL',
      bolsasRecomendadas: bolsasRecomendadas,
      alertas: alertas
    };
  }

  /**
   * Avalia gatilhos e calcula reposição determinística de Concentrado de Plaquetas (CP).
   * @param {Object} params
   * @returns {Object}
   */
  function calcularReposicaoPlaquetas(params) {
    params = params || {};
    var peso = Math.max(30, Math.min(250, Number(params.peso) || 70));
    var plaquetas = params.plaquetasAtual !== undefined ? Number(params.plaquetasAtual) : null;
    var sangramentoAtivo = params.sangramentoAtivo === true;
    var tceOuNeuro = params.tceOuNeurotrauma === true;
    var procedimento = String(params.procedimento || 'NENHUM').toUpperCase();
    var febreOuInfeccao = params.febreOuInfeccao === true || params.sepse === true;
    var suspeitaPttOuHit = params.suspeitaPttOuHit === true;

    // BLOQUEIO SENTINELA ABSOLUTO: PTT e HIT
    if (suspeitaPttOuHit) {
      return {
        indicada: false,
        bloqueioAbsoluto: true,
        categoria: 'CONTRAINDICADA_RISCO_TROMBOSE_FATAL',
        gatilhoAlvo: 0,
        unidadesRecomendadas: 0,
        aféreseRecomendada: 0,
        justificativa: '🛑 CONTRAINDICAÇÃO FORMAL ABSOLUTA: Suspeita de Púrpura Trombocitopênica Trombótica (PTT) ou Trombocitopenia Induzida por Heparina (HIT tipo II). A transfusão de plaquetas pode precipitar trombose arterial e venosa maciça catastrófica (combustível no fogo). Só transfundir em sangramento de risco iminente de morte no SNC.',
        alertas: [
          'Em PTT: Iniciar Plasmaférese de emergência com reposição de plasma e corticoterapia.',
          'Em HIT: Suspender imediatamente todas as heparinas (HNF e HBPM) e iniciar anticoagulante não-heparínico (Fondaparinux ou Argatrobana).'
        ]
      };
    }

    var gatilho = 10000;
    var justificativa = '';
    var categoria = 'PROFILATICA_MEDULAR';

    if (tceOuNeuro || procedimento.indexOf('NEURO') >= 0 || procedimento.indexOf('OCULAR') >= 0) {
      gatilho = 100000;
      categoria = 'NEUROCIRURGIA_SNC';
      justificativa = 'Neurocirurgia, trauma cranioencefálico grave ou cirurgia oftalmológica de câmara posterior. Alvo rigoroso de plaquetas >= 100.000/mcL para prevenir hematoma expansivo no SNC.';
    } else if (sangramentoAtivo || procedimento.indexOf('PUNCAO_LOMBAR') >= 0 || procedimento.indexOf('BIOPSIA') >= 0 || procedimento.indexOf('CIRURGIA_GRANDE') >= 0) {
      gatilho = 50000;
      categoria = 'SANGRAMENTO_OU_PROCEDIMENTO_INVASIVO';
      justificativa = 'Sangramento clinicamente significativo, CIVD ou necessidade de cirurgia de grande porte / punção lombar / biópsia de órgão maciço. Alvo plaquetário >= 50.000/mcL.';
    } else if (febreOuInfeccao) {
      gatilho = 20000;
      categoria = 'PROFILAXIA_COM_FATORES_DE_RISCO';
      justificativa = 'Trombocitopenia com fatores de consumo/consumo acelerado associados (febre > 38°C, sepse grave, mucosite extensa ou alterações de coagulação). Alvo >= 20.000/mcL.';
    } else {
      gatilho = 10000;
      categoria = 'PROFILAXIA_FALENCIA_MEDULAR';
      justificativa = 'Profilaxia em hipoproliferação medular estável (quimioterapia / aplasia) sem outros fatores de risco. Alvo >= 10.000/mcL.';
    }

    var indicada = (plaquetas !== null && plaquetas < gatilho);
    var unidadesRandomicas = 0;
    var aféreseRecomendada = 0;
    var incrementoEsperado = '';

    if (indicada) {
      // 1 unidade convencional a cada 10 kg de peso (ex: 70 kg -> 7 UI, teto seguro de 10 UI no adulto)
      unidadesRandomicas = Math.min(10, Math.max(4, Math.round(peso / 10)));
      // 1 aférese de doador único equivale a 6-8 unidades randômicas
      aféreseRecomendada = 1;
      incrementoEsperado = 'Elevação esperada de 30.000 a 50.000/mcL após 1 pool de aférese (ou ~5.000 a 8.000/mcL por unidade randômica em adulto de 70 kg).';
    }

    var alertas = [];
    if (peso > 150) {
      alertas.push('⚠️ OBESIDADE SEVERA (> 150 kg): O cálculo de plaquetas randômicas foi limitado ao teto padrão de 10 unidades para prevenir sobrecarga volêmica. Recomenda-se transfundir concentrado de plaquetas por aférese (1 a 2 pools).');
    }
    if (!indicada && plaquetas !== null) {
      alertas.push('Plaquetas atuais (' + plaquetas.toLocaleString('pt-BR') + '/mcL) estão acima do gatilho recomendado de ' + gatilho.toLocaleString('pt-BR') + '/mcL. Transfusão desnecessária evitada.');
    } else if (indicada) {
      alertas.push('Preferencia por Aférese: O concentrado de plaquetas por aférese reduz o número de doadores expostos e a taxa de aloimunização.');
      alertas.push('Infusão rápida: Administrar em 20 a 30 minutos em equipo com filtro específico para plaquetas.');
      alertas.push('Duração biológica: A meia-vida plaquetária transfundida é de cerca de 3 a 4 dias (ou poucas horas em estados sépticos/imunológicos).');
    }

    return {
      indicada: indicada,
      bloqueioAbsoluto: false,
      plaquetasAtual: plaquetas,
      gatilhoAlvo: gatilho,
      categoria: categoria,
      justificativa: justificativa,
      pesoKg: peso,
      unidadesRandomicasCalculadas: unidadesRandomicas,
      aféreseRecomendada: aféreseRecomendada,
      incrementoEsperado: incrementoEsperado,
      alertas: alertas
    };
  }

  /**
   * Avalia necessidade e calcula reposição determinística de Crioprecipitado.
   * @param {Object} params
   * @returns {Object}
   */
  function calcularReposicaoCrioprecipitado(params) {
    params = params || {};
    var peso = Math.max(30, Math.min(250, Number(params.peso) || 70));
    var fibrinogenio = params.fibrinogenioAtual !== undefined ? Number(params.fibrinogenioAtual) : null;
    var cenario = String(params.cenario || 'GERAL').toUpperCase();
    var sangramentoAtivo = params.sangramentoAtivo === true;

    // Gatilhos de Fibrinogênio:
    // Em HPP e Trauma Grave / PTM: meta >= 200 mg/dL (gatilho < 200)
    // Em sangramento clínico geral / CIVD: meta >= 150 mg/dL (gatilho < 150)
    // Em profilaxia assintomática: gatilho < 100 mg/dL
    var gatilhoFibrinogenio = 150;
    var alvoFibrinogenio = 200;

    if (cenario.indexOf('HPP') >= 0 || cenario.indexOf('OBSTETRIC') >= 0 || cenario.indexOf('TRAUMA') >= 0 || cenario.indexOf('PTM') >= 0) {
      gatilhoFibrinogenio = 200;
      alvoFibrinogenio = 200;
    } else if (!sangramentoAtivo) {
      gatilhoFibrinogenio = 100;
      alvoFibrinogenio = 150;
    }

    var indicada = (fibrinogenio !== null && fibrinogenio < gatilhoFibrinogenio);
    var bolsasRecomendadas = 0;
    var incrementoEsperado = '';

    if (indicada) {
      // Regra clínica: 1 bolsa para cada 7 a 10 kg de peso (habitual adulto = 1 pool de 10 bolsas)
      // Cálculo detalhado: Cada bolsa possui em média 200 a 250 mg de fibrinogênio
      var volumePlasmaticoDl = (peso * 40) / 100;
      var deficitMg = Math.max(0, alvoFibrinogenio - fibrinogenio) * volumePlasmaticoDl;
      var bolsasExatas = Math.ceil(deficitMg / 250);
      bolsasRecomendadas = Math.max(6, Math.min(15, bolsasExatas || Math.round(peso / 7)));
      incrementoEsperado = 'Elevação estimada de aproximadamente ' + Math.round((bolsasRecomendadas * 220) / volumePlasmaticoDl) + ' mg/dL de fibrinogênio plasmático.';
    }

    var alertas = [];
    if (!indicada && fibrinogenio !== null) {
      alertas.push('Fibrinogênio sérico (' + fibrinogenio + ' mg/dL) adequado para o cenário clínico (alvo >= ' + gatilhoFibrinogenio + ' mg/dL).');
    } else if (indicada) {
      alertas.push('Composição nobre: O Crioprecipitado é rico em Fibrinogênio, Fator VIII, Fator de von Willebrand (vWF) e Fator XIII.');
      alertas.push('Modo de administração: Infundir em velocidade rápida (pool de 10 unidades infundido em 15 a 30 minutos).');
    }

    return {
      indicada: indicada,
      fibrinogenioAtual: fibrinogenio,
      gatilhoFibrinogenio: gatilhoFibrinogenio,
      alvoFibrinogenio: alvoFibrinogenio,
      pesoKg: peso,
      bolsasCalculadas: bolsasRecomendadas,
      incrementoEsperado: incrementoEsperado,
      alertas: alertas
    };
  }

  /**
   * Avalia escore ISTH para Coagulação Intravascular Disseminada (CIVD Manifesta / Overt DIC).
   * @param {Object} params
   * @returns {Object}
   */
  function avaliarCivd(params) {
    params = params || {};
    var plaquetas = Number(params.plaquetas) || 150000;
    var dDimeroAumento = String(params.dDimeroAumento || 'NORMAL').toUpperCase(); // NORMAL, MODERADO, ACENTUADO
    var tpAlargadoSegundos = Number(params.tpAlargadoSegundos) || 0; // segundos acima do controle
    var fibrinogenio = Number(params.fibrinogenio) || 200;
    var temSangramento = params.sangramentoAtivo === true;

    var pontos = 0;
    var achados = [];

    // 1. Plaquetas
    if (plaquetas < 50000) {
      pontos += 2;
      achados.push({ criterio: 'Plaquetas < 50.000/mcL (' + plaquetas.toLocaleString('pt-BR') + ')', pontos: 2 });
    } else if (plaquetas <= 100000) {
      pontos += 1;
      achados.push({ criterio: 'Plaquetas entre 50.000 e 100.000/mcL (' + plaquetas.toLocaleString('pt-BR') + ')', pontos: 1 });
    } else {
      achados.push({ criterio: 'Plaquetas > 100.000/mcL', pontos: 0 });
    }

    // 2. Marcadores relacionados à fibrina (D-dímero / PDF)
    if (dDimeroAumento === 'ACENTUADO' || dDimeroAumento === 'FORTE') {
      pontos += 3;
      achados.push({ criterio: 'Aumento acentuado de marcadores de fibrina (D-dímero muito alto)', pontos: 3 });
    } else if (dDimeroAumento === 'MODERADO') {
      pontos += 2;
      achados.push({ criterio: 'Aumento moderado de marcadores de fibrina', pontos: 2 });
    } else {
      achados.push({ criterio: 'Marcadores de fibrina normais', pontos: 0 });
    }

    // 3. Tempo de Protrombina (segundos acima do controle)
    if (tpAlargadoSegundos >= 6) {
      pontos += 2;
      achados.push({ criterio: 'Tempo de Protrombina prolongado >= 6 segundos acima do controle', pontos: 2 });
    } else if (tpAlargadoSegundos >= 3) {
      pontos += 1;
      achados.push({ criterio: 'Tempo de Protrombina prolongado entre 3 e 6 segundos', pontos: 1 });
    } else {
      achados.push({ criterio: 'Tempo de Protrombina prolongado < 3 segundos', pontos: 0 });
    }

    // 4. Fibrinogênio sérico
    if (fibrinogenio < 100) {
      pontos += 1;
      achados.push({ criterio: 'Hipofibrinogenemia severa (< 100 mg/dL: ' + fibrinogenio + ' mg/dL)', pontos: 1 });
    } else {
      achados.push({ criterio: 'Fibrinogênio sérico >= 100 mg/dL', pontos: 0 });
    }

    var civdManifesta = pontos >= 5;
    var planoAcao = [];

    if (civdManifesta) {
      planoAcao.push('DIAGNÓSTICO CONFIRMADO DE CIVD MANIFESTA (Overt DIC Score >= 5). Alta mortalidade associada.');
      planoAcao.push('PRIORIDADE ABSOLUTA: Tratar agressivamente a doença de base (foco séptico, controle de descolamento de placenta, quimioterapia para leucemia promielocítica).');
      if (temSangramento) {
        if (plaquetas < 50000) planoAcao.push('Reposição de Plaquetas (alvo > 50.000/mcL) devido ao sangramento ativo.');
        if (tpAlargadoSegundos >= 3) planoAcao.push('Reposição de Plasma Fresco Congelado (PFC 15 mL/kg) para repor múltiplos fatores de coagulação.');
        if (fibrinogenio < 150) planoAcao.push('Reposição de Crioprecipitado (1 pool de 10 UI) para restaurar fibrinogênio > 150 mg/dL.');
      } else {
        planoAcao.push('Sem sangramento ativo: Tratamento direcionado exclusivamente à causa base; transfusões profiláticas de rotina são desaconselhadas para não alimentar a microtrombose.');
      }
    } else {
      planoAcao.push('Escore ISTH < 5: Não fecha critérios de CIVD manifesta no momento. Reavaliar diariamente em pacientes críticos com suspeita em evolução.');
    }

    return {
      pontosTotais: pontos,
      civdManifesta: civdManifesta,
      classificacao: civdManifesta ? 'CIVD_MANIFESTA' : 'NAO_MANIFESTA',
      achados: achados,
      planoAcao: planoAcao
    };
  }

  /**
   * Avalia e classifica diagnósticos diferenciais de Reações Transfusionais Agudas (RTA).
   * @param {Object} params
   * @returns {Object}
   */
  function avaliarReacaoTransfusional(params) {
    params = params || {};
    var febre = params.febre === true || Number(params.temperatura) >= 37.8;
    var hipotensao = params.hipotensao === true || Number(params.pas) < 90;
    var dispneia = params.dispneia === true;
    var estertores = params.estertores === true || params.edemaPulmonar === true;
    var turgenciaJugular = params.turgenciaJugular === true;
    var dorLombar = params.dorLombar === true;
    var coluria = params.coluria === true || params.urinaEscura === true;
    var urticaria = params.urticaria === true || params.prurido === true;
    var estridor = params.estridor === true || params.broncoespasmo === true;
    var calafrios = params.calafrios === true;

    var tipoReacao = 'INDETERMINADA';
    var gravidade = 'MODERADA';
    var condutaImediata = [];
    var investigacao = [];

    if (dorLombar && (coluria || hipotensao || febre)) {
      tipoReacao = 'REACAO_HEMOLITICA_AGUDA_ABO';
      gravidade = 'EMERGENCIA_MAXIMA';
      condutaImediata.push('🛑 INTERRUPÇÃO IMEDIATA E DEFINITIVA DA TRANSFUSÃO!');
      condutaImediata.push('Manter acesso venoso calibroso pérvio com infusão de Soro Fisiológico 0,9%. Não desconectar equipo da bolsa para envio ao banco de sangue.');
      condutaImediata.push('Hiper-hidratação vigorosa com cristaloides para manter diurese > 100 mL/h e prevenir necrose tubular aguda por hemoglobina livre.');
      condutaImediata.push('Suporte hemodinâmico com vasopressores (Noradrenalina) se choque persistente.');
      investigacao.push('Enviar bolsa de sangue e equipo intactos imediatamente ao Hemocentro.');
      investigacao.push('Coleta de amostra de sangue pós-reação: Teste de Coombs Direto, Hemoglobina livre plasmática, Haptoglobina, Bilirrubinas, LDH e Urina I.');
    } else if (dispneia && (estridor || (urticaria && hipotensao))) {
      tipoReacao = 'ANAFILAXIA_TRANSFUSIONAL';
      gravidade = 'EMERGENCIA_MAXIMA';
      condutaImediata.push('🛑 INTERRUPÇÃO IMEDIATA DA TRANSFUSÃO!');
      condutaImediata.push('Adrenalina 1:1.000 (0,5 mg IM no vasto lateral da coxa) IMEDIATAMENTE. Repetir em 5-10 min se necessário.');
      condutaImediata.push('Oxigenoterapia sob máscara e preparo para intubação se edema de glote.');
      condutaImediata.push('Anti-histamínico IV (Difenidramina 50 mg) + Corticoide IV (Hidrocortisona 200 a 500 mg).');
      investigacao.push('Dosar IgA sérica e anticorpos anti-IgA (suspeita de deficiência congênita de IgA).');
    } else if (dispneia && estertores && turgenciaJugular) {
      tipoReacao = 'TACO_SOBRECARGA_CIRCULATORIA';
      gravidade = 'ALTA';
      condutaImediata.push('🛑 INTERRUPÇÃO DA TRANSFUSÃO!');
      condutaImediata.push('Posicionar paciente sentado com membros pendentes.');
      condutaImediata.push('Oxigenoterapia suplementar (manter SpO2 > 94%).');
      condutaImediata.push('Furosemida 20 a 40 mg IV em bolus imediato.');
      condutaImediata.push('Vasodilatadores venosos (Nitroglicerina) se pressão arterial elevada.');
      investigacao.push('Ecocardiograma beira-leito, Radiografia de tórax e dosagem de BNP / NT-proBNP.');
    } else if (dispneia && estertores && !turgenciaJugular && !hipotensao) {
      tipoReacao = 'TRALI_LESAO_PULMONAR_AGUDA';
      gravidade = 'ALTA';
      condutaImediata.push('🛑 INTERRUPÇÃO DA TRANSFUSÃO!');
      condutaImediata.push('Suporte ventilatório protetor com PEEP moderada (VNI ou Intubação Orotraqueal).');
      condutaImediata.push('NÃO administrar diuréticos em doses agressivas se não houver hipervolemia evidente.');
      condutaImediata.push('Notificação imediata ao hemocentro para bloqueio cautelar do doador.');
      investigacao.push('Radiografia de tórax (infiltrado bilateral), gasometria arterial e pesquisa de anticorpos anti-HLA / anti-HNA no doador.');
    } else if (febre && hipotensao && calafrios) {
      tipoReacao = 'CONTAMINACAO_BACTERIANA_SEPSE';
      gravidade = 'EMERGENCIA_MAXIMA';
      condutaImediata.push('🛑 INTERRUPÇÃO IMEDIATA DA TRANSFUSÃO!');
      condutaImediata.push('Coletar hemoculturas do paciente (2 sítios) e hemocultura direta da bolsa de sangue.');
      condutaImediata.push('Iniciar antibioticoterapia de amplo espectro em até 1 hora (ex: Meropenem ou Vancomicina + Cefepime).');
      condutaImediata.push('Ressuscitação volêmica vigorosa e vasopressores conforme protocolo de choque séptico.');
      investigacao.push('Bacterioscopia por Gram imediata do conteúdo da bolsa de sangue.');
    } else if (febre && !hipotensao && !coluria && !dorLombar) {
      tipoReacao = 'RFNH_REACAO_FEBRIL_NAO_HEMOLITICA';
      gravidade = 'LEVE_A_MODERADA';
      condutaImediata.push('Pausar a infusão temporariamente para excluir hemólise aguda.');
      condutaImediata.push('Antitérmico: Dipirona 1g IV ou Paracetamol 750mg VO.');
      condutaImediata.push('Pode reiniciar transfusão somente se descartada hemólise e com regressão térmica.');
      investigacao.push('Prescrever hemocomponentes DESLEUCOCITADOS (filtrados) nas próximas transfusões para evitar recidiva.');
    } else if (urticaria && !dispneia && !hipotensao) {
      tipoReacao = 'REACAO_ALERGICA_LEVE';
      gravidade = 'LEVE';
      condutaImediata.push('Pausar a transfusão.');
      condutaImediata.push('Administrar anti-histamínico IV ou VO (ex: Difenidramina 25-50 mg ou Dexclorfeniramina).');
      condutaImediata.push('Se sintomas regredirem completamente em 20-30 minutos sem surgimento de novos sinais, a transfusão pode ser reiniciada em velocidade lenta.');
      investigacao.push('Se reação recorrente, indicar hemocomponentes lavados.');
    }

    return {
      tipoReacao: tipoReacao,
      gravidade: gravidade,
      condutaImediata: condutaImediata,
      investigacao: investigacao
    };
  }

  /**
   * Consolida a prescrição médica hemoterápica padronizada.
   * @param {Object} params
   * @returns {Object}
   */
  function gerarPrescricaoTransfusionalCompleta(params) {
    params = params || {};
    var avalChad = avaliarGatilhoTransfusionalChad(params);
    var avalPfc = params.avaliarPfc ? calcularReposicaoPfc(params) : null;
    var avalPlaq = params.avaliarPlaquetas ? calcularReposicaoPlaquetas(params) : null;
    var avalCrio = params.avaliarCrioprecipitado ? calcularReposicaoCrioprecipitado(params) : null;

    var linhas = [];
    linhas.push('═══════════════════════════════════════════════════════════');
    linhas.push('       PRESCRIÇÃO E SOLICITAÇÃO HEMOTERÁPICA BEIRA-LEITO   ');
    linhas.push('═══════════════════════════════════════════════════════════');
    linhas.push('Paciente: ' + (params.pacienteNome || 'Não identificado') + ' | Peso: ' + avalChad.pesoKg + ' kg');
    linhas.push('Indicação Clínica: ' + (params.cenarioClinico || 'Avaliação Transfusional Hospitalar'));
    linhas.push('-----------------------------------------------------------');

    if (avalChad.indicada) {
      linhas.push('1. CONCENTRADO DE HEMÁCIAS (CHAD):');
      linhas.push('   • Quantidade: ' + avalChad.bolsasCalculadas + ' unidade(s) de CHAD (' + (avalChad.bolsasCalculadas * 300) + ' mL)');
      linhas.push('   • Exames obrigatórios: Tipagem ABO/Rh, PAI e Prova de Compatibilidade Maior');
      linhas.push('   • Velocidade: ' + avalChad.recomendacaoVelocidade);
      if (avalChad.alertaTaco) {
        linhas.push('   • PREVENÇÃO DE TACO: ' + avalChad.alertaTaco);
      }
    } else {
      linhas.push('1. CONCENTRADO DE HEMÁCIAS (CHAD): NÃO INDICADO no momento (Estratégia Restritiva mantida).');
    }

    if (avalPfc && avalPfc.indicada) {
      linhas.push('\n2. PLASMA FRESCO CONGELADO (PFC):');
      linhas.push('   • Quantidade: ' + avalPfc.bolsasRecomendadas + ' bolsa(s) (~' + avalPfc.volumeTotalRecomendadoMl + ' mL - Dose ' + avalPfc.dosePorKg + ')');
      linhas.push('   • Velocidade: Infusão em 30 a 60 min por bolsa com equipo com filtro');
    }

    if (avalPlaq && avalPlaq.indicada && !avalPlaq.bloqueioAbsoluto) {
      linhas.push('\n3. CONCENTRADO DE PLAQUETAS:');
      linhas.push('   • Quantidade: 1 pool de aférese OU ' + avalPlaq.unidadesRandomicasCalculadas + ' unidades randômicas');
      linhas.push('   • Velocidade: Infusão rápida em 20 a 30 minutos em equipo próprio');
    } else if (avalPlaq && avalPlaq.bloqueioAbsoluto) {
      linhas.push('\n3. CONCENTRADO DE PLAQUETAS: BLOQUEADO POR SEGURANÇA!');
      linhas.push('   • ' + avalPlaq.justificativa);
    }

    if (avalCrio && avalCrio.indicada) {
      linhas.push('\n4. CRIOPRECIPITADO:');
      linhas.push('   • Quantidade: ' + avalCrio.bolsasCalculadas + ' bolsas (pool de crioprecipitado)');
      linhas.push('   • Velocidade: Infusão rápida em 15 a 30 minutos');
    }

    linhas.push('\n-----------------------------------------------------------');
    linhas.push('ROTINA DE SEGURANÇA TRANSFUSIONAL (PORTARIA MS 5/2017):');
    linhas.push(' • Dupla checagem obrigatória à beira do leito por dois profissionais');
    linhas.push(' • Aferição de SSVV pré-transfusão, aos 10-15 minutos e ao término');
    linhas.push(' • Interromper imediatamente e comunicar o médico em caso de febre, calafrios, dispneia ou dor lombar');
    linhas.push('═══════════════════════════════════════════════════════════');

    return {
      textoPrescricao: linhas.join('\n'),
      chad: avalChad,
      pfc: avalPfc,
      plaquetas: avalPlaq,
      crioprecipitado: avalCrio
    };
  }

  /**
   * Formata resumo executivo em Markdown para Telegram / Terminal / Cockpit.
   * @param {Object} dados
   * @returns {string}
   */
  function formatarResumoTransfusional(dados) {
    dados = dados || {};
    var out = [];
    out.push('🩸 *PAINEL DE HEMOTERAPIA & TRANSFUSÃO SANGUÍNEA*');
    out.push('════════════════════════════════════════════');

    if (dados.chad) {
      out.push('\n🩸 *Concentrado de Hemácias (CHAD):*');
      out.push('• Status: *' + (dados.chad.indicada ? 'INDICADA ✅' : 'NÃO INDICADA 🛑') + '* (' + dados.chad.estrategia + ')');
      if (dados.chad.hbInformada !== null) out.push('• Hb Atual: *' + dados.chad.hbInformada + ' g/dL* | Gatilho: *' + dados.chad.gatilhoHb + ' g/dL* | Alvo: *' + dados.chad.hbAlvo + ' g/dL*');
      if (dados.chad.indicada) {
        out.push('• Prescrição: *' + dados.chad.bolsasCalculadas + ' bolsa(s)* (~' + (dados.chad.bolsasCalculadas * 300) + ' mL)');
        out.push('• Incremento Esperado: *+' + (dados.chad.bolsasCalculadas * dados.chad.deltaEsperadoPorBolsa).toFixed(1) + ' g/dL* de Hb');
      }
      if (dados.chad.alertaTaco) out.push('• ' + dados.chad.alertaTaco);
    }

    if (dados.ptm) {
      out.push('\n🚨 *PROTOCOLO DE TRANSFUSÃO MACIÇA (PTM 1:1:1):*');
      out.push('• Ativação Recomendada: *' + (dados.ptm.ativacaoPtm ? 'SIM 🛑' : 'NÃO') + '*');
      out.push('• Escore ABC: *' + dados.ptm.abcPontos + '/4 pontos* | Índice Choque: *' + dados.ptm.shockIndex + '* (' + dados.ptm.gravidadeChoque + ')');
      out.push('• Tipo CHAD Imediato: *' + dados.ptm.tipoChadEmergencia + '*');
      if (dados.ptm.txa) {
        out.push('• Ácido Tranexâmico (TXA): *' + dados.ptm.txa.ataque + '* seguido de *' + dados.ptm.txa.manutencao + '*');
      }
    }

    if (dados.plaquetas) {
      out.push('\n🩹 *Plaquetas:*');
      if (dados.plaquetas.bloqueioAbsoluto) {
        out.push('• 🛑 *BLOQUEIO ABSOLUTO:* ' + dados.plaquetas.justificativa);
      } else {
        out.push('• Status: *' + (dados.plaquetas.indicada ? 'INDICADA' : 'NÃO INDICADA') + '* (Gatilho: ' + dados.plaquetas.gatilhoAlvo.toLocaleString('pt-BR') + '/mcL)');
        if (dados.plaquetas.indicada) out.push('• Dose: *1 Aférese* ou *' + dados.plaquetas.unidadesRandomicasCalculadas + ' UI randômicas*');
      }
    }

    if (dados.pfc && dados.pfc.indicada) {
      out.push('\n🧪 *Plasma Fresco Congelado (PFC):*');
      out.push('• Dose: *' + dados.pfc.bolsasRecomendadas + ' bolsas* (~' + dados.pfc.volumeTotalRecomendadoMl + ' mL)');
    }

    if (dados.crioprecipitado && dados.crioprecipitado.indicada) {
      out.push('\n💉 *Crioprecipitado:*');
      out.push('• Dose: *' + dados.crioprecipitado.bolsasCalculadas + ' bolsas* (Pool)');
    }

    return out.join('\n');
  }

  return {
    avaliarGatilhoTransfusionalChad: avaliarGatilhoTransfusionalChad,
    calcularProtocoloTransfusaoMaciça: calcularProtocoloTransfusaoMaciça,
    calcularReposicaoPfc: calcularReposicaoPfc,
    calcularReposicaoPlaquetas: calcularReposicaoPlaquetas,
    calcularReposicaoCrioprecipitado: calcularReposicaoCrioprecipitado,
    avaliarCivd: avaliarCivd,
    avaliarReacaoTransfusional: avaliarReacaoTransfusional,
    gerarPrescricaoTransfusionalCompleta: gerarPrescricaoTransfusionalCompleta,
    formatarResumoTransfusional: formatarResumoTransfusional
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = TransfusaoSanguineaService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_urologia_colica_nefretica.js
// ==============================================================================

/**
 * ==============================================================================
 * ULTRA ROTINA - MÓDULO DE UROLOGIA & NEFROLOGIA
 * ==============================================================================
 * Manejo de Cólica Nefrética Aguda e Litíase Urinária
 * Diretrizes SBU / EAU
 * 
 * Escopo:
 * - Algoritmo escalonado de analgesia de emergência
 * - Terapia Expulsiva Médica (MET)
 * - Checklist de gravidade e indicação cirúrgica urgente
 * ==============================================================================
 */

var UrologiaColicaNefreticaService = (function () {
  'use strict';

  function avaliarGravidade(dados) {
    var gravidade = false;
    var motivos = [];
    
    if (dados.rimUnico) { gravidade = true; motivos.push("Rim Único"); }
    if (dados.sepseOuInfeccao) { gravidade = true; motivos.push("Sepse / Infecção urinária associada à obstrução"); }
    if (dados.anuriaOuOliguria) { gravidade = true; motivos.push("Anúria ou oligúria severa (IRA pós-renal bilateral ou em rim único)"); }
    if (dados.dorRefrataria) { gravidade = true; motivos.push("Dor refratária persistente a analgesia opioide e AINE otimizada"); }
    if (dados.gestanteComComplicacao) { gravidade = true; motivos.push("Gestante com cólica refratária ou ameaça de trabalho de parto prematuro"); }

    var conduta_cirurgica = "";
    if (gravidade) {
        conduta_cirurgica = "🚨 **EMERGÊNCIA UROLÓGICA (DESCOMPRESSÃO IMEDIATA):** Indicação absoluta de descompressão urgente da via excretora com Cateter Duplo J ou Nefrostomia Percutânea. Acionar Urologia IMEDIATAMENTE.";
    } else {
        conduta_cirurgica = "✅ **SEM CRITÉRIOS DE URGÊNCIA CIRÚRGICA:** Manejo clínico inicial. Alta após analgesia com seguimento ambulatorial pela Urologia.";
    }

    return { 
        urgencia: gravidade, 
        motivos: motivos, 
        conduta: conduta_cirurgica 
    };
  }

  function avaliarAnalgesia(dados) {
    var relatorio = [];
    relatorio.push("💊 **ANALGESIA DE EMERGÊNCIA (Escalonada):**");
    
    if (dados.clcr < 30) {
        relatorio.push("⚠️ **ALERTA DE SEGURANÇA:** ClCr < 30 mL/min ou DRC dialítica. **AINEs SÃO CONTRAINDICADOS.**");
        relatorio.push("- **1ª Linha:** Dipirona 1g IV + Opioides de resgate imediato.");
        relatorio.push("- **Opioides:** Tramadol 50-100mg IV (infusão lenta em 100mL SF em 20 min) OU Morfina 2 a 5mg IV lento.");
        relatorio.push("- Evitar hidratação intravenosa vigorosa se anúria/oligúria ou risco de EAP.");
    } else if (dados.gestante) {
        relatorio.push("⚠️ **ALERTA GESTANTE:**");
        relatorio.push("- **AINEs são contraindicados** no 3º trimestre (fechamento precoce do ducto arterioso e oligoâmnio). Seu uso no 1º e 2º trimestre é discutível (evitar se possível).");
        relatorio.push("- **Escolha Segura:** Dipirona 1g IV e Tramadol/Morfina IV em doses baixas para controle da dor aguda.");
    } else {
        relatorio.push("- **1ª Linha (AINEs):** Padrão-ouro (SBU/EAU). Promovem analgesia ao reduzir a síntese de prostaglandinas, diminuindo o fluxo plasmático renal, a pressão intratubular e o edema ureteral local.");
        relatorio.push("  - **Cetoprofeno:** 100mg IV (diluído em 100mL SF 0.9%, correr em 20 min).");
        relatorio.push("  - **Ou Diclofenaco:** 75mg IM profundo (NÃO fazer IV pelo risco de flebite e choque).");
        relatorio.push("  - **Ou Tenoxicam:** 40mg IV lento.");
        relatorio.push("- **Adjuvante Base:** Dipirona 1g IV lento.");
        relatorio.push("- **2ª Linha (Resgate para Dor Refratária):** Tramadol 50-100mg IV ou Morfina 2 a 5mg IV.");
    }
    
    relatorio.push("- **Antiespasmódicos (ex: Escopolamina/Buscopan):** Uso isolado não tem superioridade aos AINEs na cólica nefrética verdadeira, e pode piorar taquicardia ou boca seca, porém pode ser associado para conforto visceral se espasmo intenso.");
    relatorio.push("- **Hidratação:** **NÃO faça hidratação vigorosa beira-leito.** Hiper-hidratação agrava a distensão da cápsula renal e piora a dor, não " + "''empurra''" + " a pedra.");

    return relatorio.join('\n');
  }

  function avaliarTerapiaExpulsiva(dados) {
    var relatorio = [];
    relatorio.push("🩺 **TERAPIA EXPULSIVA MÉDICA (MET):**");
    
    var t = dados.tamanhoCalculo;
    var loc = (dados.localizacao || '').toLowerCase();
    var distais_valida = loc.includes('distal') || loc.includes('juv') || loc === ''; // se vazio, assume chance

    if (t === 0 || isNaN(t)) {
        relatorio.push("- Indicação padronizada para cálculos de **ureter distal entre 5 e 10 mm**.");
        relatorio.push("- **Droga de Escolha:** Tansulosina 0.4mg VO, 1x/dia, por até 4 semanas.");
        relatorio.push("- *Atenção:* Risco de hipotensão postural. Pode ser associado a corticoide oral por 5-7 dias (ex: Deflazacorte 30mg) para potencializar o efeito anti-inflamatório local.");
    } else if (t >= 5 && t <= 10 && distais_valida) {
        relatorio.push("- **Indicação Confirmada:** Cálculo ureteral de " + t + " mm.");
        relatorio.push("- **Prescrição:** Tansulosina 0.4mg VO, 1x ao dia (preferencialmente após uma refeição). Duração de até 4 semanas.");
        relatorio.push("- Corticoterapia adjuvante curta (ex: Deflazacorte 30mg VO/dia por 5 a 7 dias) pode reduzir o edema pericalculoso e facilitar a expulsão.");
    } else if (t > 10) {
        relatorio.push("- **CONTRAINDICADA:** Cálculo > 10 mm (" + t + " mm). A probabilidade de eliminação espontânea é ínfima.");
        relatorio.push("- Indicado tratamento urológico ativo (Ureterolitotripsia Endoscópica a Laser ou LECO).");
    } else if (t < 5) {
        relatorio.push("- **USO OPCIONAL/DISCUTÍVEL:** Cálculos < 5 mm (" + t + " mm) têm alta taxa de eliminação espontânea (> 80-90%).");
        relatorio.push("- A Tansulosina tem benefício marginal neste grupo, mas pode ser prescrita para alívio de sintomas miccionais irritativos.");
    } else {
        relatorio.push("- A Tansulosina 0.4mg é mais eficaz em cálculos de ureter distal (5 a 10 mm). Localizações altas (ureter proximal/pelve) têm menor taxa de sucesso com MET.");
    }
    
    return relatorio.join('\n');
  }

  function avaliar(parametros) {
    var clcr = typeof parametros.clcr === 'number' ? parametros.clcr : 100;
    var tamanho = typeof parametros.tamanhoCalculo === 'number' ? parametros.tamanhoCalculo : 0;
    var loc = parametros.localizacao || '';
    
    var gravidade = avaliarGravidade({
        rimUnico: !!parametros.rimUnico,
        sepseOuInfeccao: !!parametros.sepseOuInfeccao,
        anuriaOuOliguria: !!parametros.anuriaOuOliguria,
        dorRefrataria: !!parametros.dorRefrataria,
        gestanteComComplicacao: !!parametros.gestante && !!parametros.dorRefrataria
    });

    var analgesia = avaliarAnalgesia({
        clcr: clcr,
        gestante: !!parametros.gestante
    });

    var met = avaliarTerapiaExpulsiva({
        tamanhoCalculo: tamanho,
        localizacao: loc
    });

    return {
        parametros: parametros,
        gravidade: gravidade,
        analgesia: analgesia,
        met: met
    };
  }

  function formatarTextoTelegram(resultado) {
    var txt = "🪨 *UROLOGIA & NEFROLOGIA — CÓLICA NEFRÉTICA E LITÍASE*\n\n";
    
    txt += resultado.gravidade.conduta + "\n";
    if (resultado.gravidade.motivos.length > 0) {
        txt += "📌 *Critérios de Gravidade Identificados:*\n";
        for (var i = 0; i < resultado.gravidade.motivos.length; i++) {
            txt += "- " + resultado.gravidade.motivos[i] + "\n";
        }
    }
    txt += "\n";
    
    txt += resultado.analgesia + "\n\n";
    txt += resultado.met + "\n\n";

    txt += "🩺 *CONDUTA BEIRA-LEITO / UBS (MÉDICO GENERALISTA):*\n";
    txt += "• *Hidratação:* NÃO hiper-hidratar na crise aguda. Ingesta hídrica forçada aumenta a pressão intracavitária e agrava a dor.\n";
    txt += "• *Critérios de Alta com Segurança:* Paciente assintomático após analgesia, sem febre/sepse, tolerando líquidos via oral e sem sinais de IRA.\n";
    txt += "• *Orientações ao Paciente:* Coar a urina para recuperar o cálculo para análise. Retornar imediatamente se febre (> 37,8°C), calafrios, vômitos ou dor refratária.\n\n";

    txt += "🚨 *CRITÉRIOS DE ENCAMINHAMENTO À UROLOGIA:*\n";
    txt += "• *Urgente (Pronto-Socorro):* Obstrução com infecção/sepse urinária (febre/piúria), rim único funcionante, anúria/IRA obstrutiva ou dor refratária a opioides.\n";
    txt += "• *Ambulatorial:* Cálculo > 10 mm, falha de expulsão após 4 semanas de Tansulosina (MET) ou litíase de repetição/coraliforme.\n";

    return txt;
  }

  function extrairParametrosTexto(texto) {
    var limpo = texto.toLowerCase();
    var p = {};
    
    // Extrair tamanho do calculo em mm
    var mmMatch = limpo.match(/(\d+(?:[.,]\d+)?)\s*(mm|milimetros|milímetros)/);
    if (mmMatch) {
        p.tamanhoCalculo = parseFloat(mmMatch[1].replace(',', '.'));
    }

    // Extrair clearance
    var clcrMatch = limpo.match(/clcr[\s:=]*(\d+)/) || limpo.match(/clearance[\s:=]*(\d+)/);
    if (clcrMatch) {
        p.clcr = parseInt(clcrMatch[1], 10);
    } else if (/(dialise|diálise|drc v|drc 5|falencia renal)/.test(limpo)) {
        p.clcr = 10;
    } else {
        p.clcr = 100;
    }

    // Localizacao
    if (/(distal|juv|juncao ureterovesical|junção)/.test(limpo)) {
        p.localizacao = 'distal';
    } else if (/(proximal|pelve|medio|médio)/.test(limpo)) {
        p.localizacao = 'proximal';
    } else {
        p.localizacao = '';
    }

    // Gravidade
    p.rimUnico = /(rim unico|rim único|monoreno|nefrectomizado)/.test(limpo);
    p.sepseOuInfeccao = /(sepse|infeccao|infecção|itu|febre|piuria|calafrio)/.test(limpo);
    p.anuriaOuOliguria = /(anuria|anúria|oliguria|oligúria|sem urinar|urina escassa)/.test(limpo);
    p.dorRefrataria = /(dor refrataria|refratário|refratario|nao melhora com morfina|opioide)/.test(limpo);
    p.gestante = /(gestante|gravida|grávida|prenhez)/.test(limpo);

    return p;
  }

  return {
    avaliarGravidade: avaliarGravidade,
    avaliarAnalgesia: avaliarAnalgesia,
    avaliarTerapiaExpulsiva: avaliarTerapiaExpulsiva,
    avaliar: avaliar,
    formatarTextoTelegram: formatarTextoTelegram,
    extrairParametrosTexto: extrairParametrosTexto
  };
})();

if (typeof module !== 'undefined' && typeof module.exports !== 'undefined') {
  module.exports = UrologiaColicaNefreticaService;
}


// ==============================================================================
// ARQUIVO FONTE: 02_via_aerea_dificil.js
// ==============================================================================

/**
 * ==============================================================================
 * MÓDULO 02: MANEJO DE VIA AÉREA DIFÍCIL E SEQUÊNCIA RÁPIDA DE INTUBAÇÃO (RSI)
 * ==============================================================================
 * Diretrizes Clínicas Oficiais:
 *  - ASA Difficult Airway Management Guidelines (American Society of Anesthesiologists 2022)
 *  - DAS Guidelines for Management of Unanticipated Difficult Intubation in Adults (2015)
 *  - Vortex Approach for Airway Emergencies
 *  - Recomendações da Sociedade Brasileira de Anestesiologia (SBA) e AMIB
 *
 * PILARES CLÍNICOS DETERMINÍSTICOS:
 *  1. Predição de Via Aérea Difícil (LEMON Score e MOANS/ROMA):
 *     - Escore LEMON (Look, Evaluate 3-3-2, Mallampati, Obstruction, Neck mobility)
 *     - Escore MOANS para Ventilação sob Máscara Facial difícil
 *  2. Sequência Rápida de Intubação (RSI - 7 Ps):
 *     - Cálculo posológico determinístico de Hipnóticos (Etomidato, Cetamina, Propofol, Midazolam)
 *       e Bloqueadores Neuromusculares (Succinilcolina vs Rocurônio)
 *     - Bloqueio sentinela absoluto de Succinilcolina em contraindicações de hipercalemia e denervação
 *     - Alerta de Choque Peri-intubação (Índice de Choque >= 0.8) exigindo ressuscitação prévia
 *     - Dose de resgate com Sugamadex (16 mg/kg) para reversão imediata de Rocurônio
 *  3. Algoritmo Passo-a-Passo de Resgate e Cenário CICO (Cannot Intubate, Cannot Oxygenate):
 *     - Plano A (Laringoscopia/Videolaringoscopia/Bougie - máx 3 tentativas)
 *     - Plano B (Dispositivo Supraglótico de 2ª geração com canal gástrico - máx 2 tentativas)
 *     - Plano C (Máscara Facial a 2 operadores)
 *     - Cenário CICO: Acesso Frontal de Pescoço de Emergência (eFONA) com Cricotireoidostomia
 *       cirúrgica Scalpel-Bougie-Tube imediata (bisturi nº 10, bougie e tubo 6.0 com cuff)
 * ==============================================================================
 */

var ViaAereaDificilService = (function() {
  'use strict';

  /**
   * Avalia a dificuldade de intubação pela regra mnemônica LEMON.
   * @param {Object} params
   * @returns {Object}
   */
  function avaliarLemon(params) {
    params = params || {};
    var pontos = 0;
    var achados = [];

    // L - Look externally (Trauma facial, barba densa, retrognatismo, obesidade, pescoço curto/largo)
    var look = params.lookExterno || params.look || false;
    if (look) {
      pontos += 1;
      var descLook = typeof look === 'string' ? look : 'Características anatômicas externas desfavoráveis (ex: barba, retrognatismo, trauma, pescoço curto)';
      achados.push({ criterio: 'L (Look)', detalhe: descLook, pontos: 1 });
    }

    // E - Evaluate 3-3-2 rule
    // 3 dedos abertura bucal, 3 dedos distância tireomentoniana, 2 dedos distância hioide-tireóide
    var aberturaBocaMenor3 = params.aberturaBocaMenor3Dedos || params.aberturaBoca < 4;
    var tireomentonianaMenor3 = params.distanciaTireomentonianaMenor3Dedos || params.distanciaTireomentoniana < 6;
    var hioideTireoideMenor2 = params.distanciaHioideCartilagemMenor2Dedos || params.distanciaHioideCartilagem < 2;

    var falha332Count = 0;
    if (aberturaBocaMenor3) falha332Count++;
    if (tireomentonianaMenor3) falha332Count++;
    if (hioideTireoideMenor2) falha332Count++;

    if (falha332Count > 0) {
      pontos += falha332Count;
      achados.push({
        criterio: 'E (Evaluate 3-3-2)',
        detalhe: 'Comprometimento da regra 3-3-2 (' + falha332Count + ' item/itens alterados: ' +
          (aberturaBocaMenor3 ? '[Abertura de boca < 3 dedos / < 4 cm] ' : '') +
          (tireomentonianaMenor3 ? '[Distância tireomentoniana < 3 dedos / < 6 cm] ' : '') +
          (hioideTireoideMenor2 ? '[Distância hioide-tireóide < 2 dedos]' : '') + ')',
        pontos: falha332Count
      });
    }

    // M - Mallampati (Classe III e IV são preditores de intubação difícil)
    var mallampati = params.mallampati ? Number(params.mallampati) : null;
    if (mallampati === 3 || mallampati === 4) {
      pontos += 1;
      achados.push({ criterio: 'M (Mallampati)', detalhe: 'Mallampati Classe ' + mallampati + ' (palato mole pouco ou não visível)', pontos: 1 });
    }

    // O - Obstruction / Obesidade (Estridor, hematoma, abscesso periamigdaliano, IMC >= 30)
    var obstrucao = params.obstrucao || params.estridor || params.corpoEstranho || (params.imc && params.imc >= 30);
    if (obstrucao) {
      pontos += 1;
      achados.push({ criterio: 'O (Obstruction/Obesity)', detalhe: 'Presença de obstrução de via aérea alta, estridor ou obesidade (IMC >= 30)', pontos: 1 });
    }

    // N - Neck mobility (Restrição de extensão cervical, colar cervical de trauma, espondilite)
    var pescoco = params.mobilidadeCervicalReduzida || params.colarCervical || params.espondilite;
    if (pescoco) {
      pontos += 1;
      achados.push({ criterio: 'N (Neck mobility)', detalhe: 'Restrição da mobilidade cervical ou colar cervical rígido', pontos: 1 });
    }

    var classificacao = '';
    var risco = '';
    var recomendacoes = [];

    if (pontos <= 1) {
      classificacao = 'Baixo risco de via aérea difícil';
      risco = 'BAIXO';
      recomendacoes = [
        'Equipamento padrão de intubação checado (laringoscópio testado, lâmina adequada, tubo com guia e cuff testado).',
        'Aspiração rígida Yankauer ligada e funcionando beira-leito.',
        'Manter sempre disponível plano B caso ocorra falha imprevista.'
      ];
    } else if (pontos <= 3) {
      classificacao = 'Risco moderado de via aérea difícil';
      risco = 'MODERADO';
      recomendacoes = [
        'Videolaringoscópio testado e disponível imediatamente na sala.',
        'Utilizar Bougie (introdutor de Eschmann) de 1ª linha na laringoscopia.',
        'Separar dispositivo supraglótico de 2ª geração (máscara laríngea com canal gástrico) pronto para inserção.',
        'Garantir profissional com experiência em intubação presente ou acionado na sala.'
      ];
    } else {
      classificacao = 'Alto risco de via aérea difícil';
      risco = 'ALTO';
      recomendacoes = [
        'ALERTA CRÍTICO: Alta probabilidade de falha na laringoscopia direta.',
        'Videolaringoscópio mandatório como primeira escolha.',
        'Presença física obrigatória de médico sênior experiente / anestesiologista antes de qualquer indução.',
        'Se paciente cooperativo e sem hipoxemia extrema: avaliar indicação de Intubação Acordado com Fibrobroncoscópio.',
        'Separar e deixar aberto na sala kit de Cricotireoidostomia Cirúrgica (bisturi nº 10, bougie e tubo 6.0).',
        'Evitar múltiplas tentativas de laringoscopia direta (máximo 2 a 3 tentativas) para evitar edema/sangramento catastrófico.'
      ];
    }

    return {
      pontos: pontos,
      risco: risco,
      classificacao: classificacao,
      achados: achados,
      recomendacoes: recomendacoes
    };
  }

  /**
   * Avalia a dificuldade de ventilação sob máscara facial (Mnemônico MOANS).
   * @param {Object} params
   * @returns {Object}
   */
  function avaliarVentilacaoMascara(params) {
    params = params || {};
    var pontos = 0;
    var fatores = [];

    if (params.barbaDensa || params.traumaFacial || params.deformidadeFacial) {
      pontos += 1;
      fatores.push('M (Mask seal): Barba volumosa, sangue ou deformidade anatômica impedindo acoplamento da máscara');
    }
    if ((params.imc && params.imc >= 30) || params.obesidade || params.gestanteTerceiroTri || params.apneiaSono) {
      pontos += 1;
      fatores.push('O (Obesity/Obstruction): Obesidade (IMC >= 30), SAOS ou gestação avançada aumentando resistência');
    }
    if (params.idade && Number(params.idade) >= 55) {
      pontos += 1;
      fatores.push('A (Age >= 55): Idade avançada associada à perda de elasticidade e tônus tecidual');
    }
    if (params.edentulo) {
      pontos += 1;
      fatores.push('N (No teeth): Paciente edêntulo com colapso das bochechas dificultando a vedação');
    }
    if (params.asmaGrave || params.sdra || params.rigidezPulmonar || params.estridor) {
      pontos += 1;
      fatores.push('S (Stiffness): Complacência pulmonar reduzida ou resistência aumentada exigindo altas pressões');
    }

    var risco = 'BAIXO';
    var conduta = [];
    if (pontos >= 3) {
      risco = 'ALTO';
      conduta = [
        'Ventilação a duas mãos e dois operadores obrigatória (técnica two-hand C-E com 1 operador vedando e outro ventilando).',
        'Inserção precoce de Cânula Orofaríngea (Guedel) do tamanho correto (comissura labial ao ângulo da mandíbula).',
        'Utilizar válvula PEEP na bolsa-válvula-máscara.',
        'Se falha persistente na ventilação: transição imediata para Dispositivo Supraglótico de 2ª geração.'
      ];
    } else if (pontos === 2) {
      risco = 'MODERADO';
      conduta = [
        'Ter cânula de Guedel à mão imediatamente.',
        'Estar pronto para ventilação a 4 mãos se a SpO2 cair abaixo de 92%.',
        'Ajustar posicionamento cervical (posição olfativa ou elevação do coxim occipital).'
      ];
    } else {
      conduta = [
        'Ventilação habitual com bolsa-válvula-máscara monofacial.',
        'Manter boa vedação com técnica C-E.'
      ];
    }

    return {
      pontos: pontos,
      risco: risco,
      fatores: fatores,
      conduta: conduta
    };
  }

  /**
   * Calcula posologia e plano determinístico para Sequência Rápida de Intubação (RSI - 7 Ps).
   * @param {Object} params
   * @returns {Object}
   */
  function calcularRsi(params) {
    params = params || {};
    var pesoKg = Number(params.pesoKg) || 70;
    var condicaoClinica = (params.condicaoClinica || 'estavel').toLowerCase();
    var pas = params.pas !== undefined ? Number(params.pas) : null;
    var fc = params.fc !== undefined ? Number(params.fc) : null;
    var indiceChoque = (pas && fc && pas > 0) ? (fc / pas) : null;

    var alertasCriticos = [];

    // Alerta de Choque Peri-intubação
    var riscoColapsoHemodinamico = false;
    if ((pas !== null && pas < 90) || (indiceChoque !== null && indiceChoque >= 0.8)) {
      riscoColapsoHemodinamico = true;
      alertasCriticos.push(
        "ALERTA VERMELHO DE CHOQUE PERI-INTUBAÇÃO: Índice de Choque elevado (" +
        (indiceChoque ? indiceChoque.toFixed(2) : "PAS < 90") +
        "). Alto risco de PCR e colapso circulatório imediato após sedação/bloqueio! Ressuscitação hemodinâmica OBRIGATÓRIA ANTES DA INDUÇÃO: infundir cristaloide ou vasopressor push-dose (Noradrenalina 10-20 mcg IV ou Fenilefrina 50-100 mcg IV)."
      );
    }

    // Seleção e cálculo do Hipnótico
    var hipnotico = params.hipnoticoEscolhido ? params.hipnoticoEscolhido.toLowerCase() : null;
    if (!hipnotico) {
      if (riscoColapsoHemodinamico || condicaoClinica.indexOf('choque') >= 0 || condicaoClinica.indexOf('sepse') >= 0) {
        hipnotico = 'etomidato';
      } else if (condicaoClinica.indexOf('asma') >= 0 || condicaoClinica.indexOf('broncoespasmo') >= 0) {
        hipnotico = 'cetamina';
      } else if (condicaoClinica.indexOf('status') >= 0 || condicaoClinica.indexOf('convuls') >= 0) {
        hipnotico = 'propofol';
      } else {
        hipnotico = 'etomidato';
      }
    }

    var doseHipnotico = {};
    if (hipnotico === 'etomidato') {
      var mgEtom = +(pesoKg * 0.3).toFixed(1);
      var mlEtom = +(mgEtom / 2.0).toFixed(1); // 2 mg/mL
      doseHipnotico = {
        farmaco: 'Etomidato',
        doseMg: mgEtom,
        apresentacao: 'Ampola 20 mg/10 mL (2 mg/mL)',
        volumeMl: mlEtom,
        posologia: mgEtom + ' mg (' + mlEtom + ' mL) IV em bolus rápido',
        justificativa: 'Fármaco de excelência hemodinâmica, mantendo estabilidade de pressão arterial e perfusão coronariana.'
      };
    } else if (hipnotico === 'cetamina') {
      var mgCet = +(pesoKg * 2.0).toFixed(1);
      var mlCet = +(mgCet / 50.0).toFixed(1); // 50 mg/mL
      doseHipnotico = {
        farmaco: 'Cetamina',
        doseMg: mgCet,
        apresentacao: 'Frasco-ampola 500 mg/10 mL (50 mg/mL)',
        volumeMl: mlCet,
        posologia: mgCet + ' mg (' + mlCet + ' mL) IV em bolus rápido',
        justificativa: 'Potente broncodilatador e simpatomimético indireto, preservando drive e pressão arterial.'
      };
    } else if (hipnotico === 'propofol') {
      var doseKgProp = riscoColapsoHemodinamico ? 1.0 : 2.0;
      var mgProp = +(pesoKg * doseKgProp).toFixed(1);
      var mlProp = +(mgProp / 10.0).toFixed(1); // 10 mg/mL (1%)
      doseHipnotico = {
        farmaco: 'Propofol',
        doseMg: mgProp,
        apresentacao: 'Ampola 200 mg/20 mL (10 mg/mL a 1%)',
        volumeMl: mlProp,
        posologia: mgProp + ' mg (' + mlProp + ' mL) IV em bolus lento (cuidado com vasodilatação)',
        justificativa: 'Excelente sedativo e anticonvulsivante; requer vigilância rigorosa de hipotensão profunda.'
      };
      if (riscoColapsoHemodinamico) {
        alertasCriticos.push("AVISO: Propofol causa vasodilatação e inotropismo negativo marcados. Se paciente instável, preferir Etomidato ou Cetamina.");
      }
    } else if (hipnotico === 'midazolam') {
      var mgMid = +(pesoKg * 0.25).toFixed(1);
      var mlMid = +(mgMid / 5.0).toFixed(1); // 5 mg/mL
      doseHipnotico = {
        farmaco: 'Midazolam',
        doseMg: mgMid,
        apresentacao: 'Ampola 15 mg/3 mL (5 mg/mL)',
        volumeMl: mlMid,
        posologia: mgMid + ' mg (' + mlMid + ' mL) IV em bolus',
        justificativa: 'Alternativa quando Etomidato ou Cetamina indisponíveis; início de ação mais demorado (2 a 3 min).'
      };
    }

    // Seleção e cálculo do Bloqueador Neuromuscular (BNM)
    var contraindicacoesSuccinilcolina = params.contraindicacoesSuccinilcolina || {};
    var succinilcolinaContraindicada = false;
    var motivoBloqueioSuccinilcolina = [];

    if (contraindicacoesSuccinilcolina.hipercalemia || params.kSérico && params.kSérico > 5.5) {
      succinilcolinaContraindicada = true;
      motivoBloqueioSuccinilcolina.push("Hipercalemia confirmada ou fortemente suspeita (risco de fibrilação ventricular/assistolia fatal)");
    }
    if (contraindicacoesSuccinilcolina.queimaduraGrave || params.queimaduraMais24h) {
      succinilcolinaContraindicada = true;
      motivoBloqueioSuccinilcolina.push("Grande queimado após 24-48h de evolução (proliferação maciça de receptores nicotínicos extrajuncionais)");
    }
    if (contraindicacoesSuccinilcolina.esmagamento || params.rabdomioliseMais24h) {
      succinilcolinaContraindicada = true;
      motivoBloqueioSuccinilcolina.push("Lesão por esmagamento / Rabdomiólise com mais de 24h");
    }
    if (contraindicacoesSuccinilcolina.denervacao || params.avcMais72h || params.traumaMedularMais72h) {
      succinilcolinaContraindicada = true;
      motivoBloqueioSuccinilcolina.push("Denervação motora crônica, paraplegia ou AVC > 72 horas");
    }
    if (contraindicacoesSuccinilcolina.hipertermiaMaligna) {
      succinilcolinaContraindicada = true;
      motivoBloqueioSuccinilcolina.push("Histórico pessoal ou familiar confirmado de Hipertermia Maligna (gatilho farmacogenético fatal)");
    }

    var bnmEscolhido = params.bloqueadorEscolhido ? params.bloqueadorEscolhido.toLowerCase() : null;
    if (succinilcolinaContraindicada) {
      bnmEscolhido = 'rocuronio';
      alertasCriticos.push(
        "CONTRAINDICAÇÃO ABSOLUTA DA SUCCINILCOLINA DETECTADA: " + motivoBloqueioSuccinilcolina.join('; ') +
        ". Succinilcolina BLOQUEADA pelo sistema. Utilizar mandatoriamente Rocurônio na dose de RSI."
      );
    } else if (!bnmEscolhido) {
      bnmEscolhido = 'succinilcolina';
    }

    var doseBnm = {};
    if (bnmEscolhido === 'rocuronio') {
      var mgRoc = +(pesoKg * 1.2).toFixed(1); // Dose de RSI = 1.2 mg/kg
      var mlRoc = +(mgRoc / 10.0).toFixed(1); // 10 mg/mL
      var doseSugamadexResgate = +(pesoKg * 16.0).toFixed(1);
      doseBnm = {
        farmaco: 'Rocurônio',
        doseMg: mgRoc,
        apresentacao: 'Frasco-ampola 50 mg/5 mL (10 mg/mL)',
        volumeMl: mlRoc,
        posologia: mgRoc + ' mg (' + mlRoc + ' mL) IV em bolus imediato após o hipnótico',
        tempoInicio: '60 segundos',
        duracaoAcao: '40 a 60 minutos',
        antidotoResgate: 'Sugamadex 16 mg/kg (' + doseSugamadexResgate + ' mg IV em bolus) para reversão imediata de emergência se via aérea não for obtida.'
      };
    } else {
      var mgSucc = +(pesoKg * 1.5).toFixed(1); // 1.0 a 1.5 mg/kg
      var mlSucc = +(mgSucc / 10.0).toFixed(1); // 100 mg reconstituído em 10 mL (10 mg/mL)
      doseBnm = {
        farmaco: 'Succinilcolina',
        doseMg: mgSucc,
        apresentacao: 'Frasco-ampola 100 mg pó liofilizado (reconstituir com 10 mL de AD = 10 mg/mL)',
        volumeMl: mlSucc,
        posologia: mgSucc + ' mg (' + mlSucc + ' mL) IV em bolus imediato após o hipnótico',
        tempoInicio: '45 a 60 segundos',
        duracaoAcao: '6 a 10 minutos (bloqueador despolarizante de curta duração)',
        antidotoResgate: 'Não há antídoto específico direto. Aguardar metabolismo pela colinesterase plasmática sob ventilação de resgate.'
      };
    }

    // Estruturação dos 7 Ps da RSI
    var passosRsi = [
      {
        passo: '1. Preparação (P-10 min)',
        acoes: [
          'Checar laringoscópio testado com luz brilhante e videolaringoscópio na sala.',
          'Separar tubos orotraqueais (7.5 e 8.0 para homens; 7.0 e 7.5 para mulheres) com cuff testado e fio guia/Bougie lubrificado.',
          'Garantir aspiração rígida tipo Yankauer funcional e fixada na cabeceira.',
          'Acesso venoso calibroso (abocath 18 ou 16G) testado com fluxo livre.',
          'Monitorização contínua: Cardioscopia, SpO2, PNI a cada 2 min e Capnografia ligada.'
        ]
      },
      {
        passo: '2. Pré-oxigenação (P-5 min)',
        acoes: [
          'Ofertar O2 a 100% por 3 minutos com máscara com reservatório a 15 L/min (ou 8 respirações em capacidade vital).',
          'Evitar ventilação com pressão positiva com bolsa-válvula-máscara se SpO2 > 92% (prevenir distensão gástrica e regurgitação).',
          'Instalar oxigenação apneica contínua via cateter nasal a 15 L/min durante todo o procedimento.'
        ]
      },
      {
        passo: '3. Pré-tratamento / Otimização (P-3 min)',
        acoes: [
          riscoColapsoHemodinamico
            ? 'Ressuscitação hemodinâmica imediata: infundir bolus de cristaloide ou vasopressor push-dose (Noradrenalina 10-20 mcg).'
            : 'Otimização hemodinâmica e posicionamento adequado (sniffing position / rampa de elevação se obeso).',
          'Se hipertensão intracraniana ou dissecção: considerar Fentanil 2-3 mcg/kg 3 minutos antes da indução para atenuar descarga simpática.'
        ]
      },
      {
        passo: '4. Paralisia com Indução (P-0 min)',
        acoes: [
          'Injetar Hipnótico em bolus imediato: ' + doseHipnotico.posologia + '.',
          'Imediatamente após, injetar Bloqueador Neuromuscular: ' + doseBnm.posologia + '.',
          'Não ventilar com máscara durante o tempo de latência (45-60s) se SpO2 estável.'
        ]
      },
      {
        passo: '5. Posicionamento e Proteção (P+30 seg)',
        acoes: [
          'Aguardar relaxamento da musculatura mandibular (testar flacidez sem tocar na corda vocal).',
          'Posição olfativa estrita (flexão cervical inferior e extensão atlanto-occipital).',
          'Pressão cricoidea (Manobra de Sellick) NÃO é recomendada rotineiramente (pode piorar a visão laringoscópica).'
        ]
      },
      {
        passo: '6. Passagem do Tubo com Laringoscopia (P+45 a 60 seg)',
        acoes: [
          'Inserir lâmina pela comissura labial direita rebatendo a língua para a esquerda.',
          'Visualizar epiglote e cordas vocais; utilizar Bougie se Cormack-Lehane II ou III.',
          'Passar o tubo sob visão direta e avançar até o cuff ultrapassar as cordas vocais em 1 a 2 cm.',
          'Insuflar o cuff imediatamente com seringa (pressão alvo 20 a 30 cmH2O).'
        ]
      },
      {
        passo: '7. Pós-intubação (P+1 min)',
        acoes: [
          'Confirmar posicionamento com Capnografia de onda (padrão ouro confirmatório).',
          'Auscultar 5 pontos: epigástrio (silêncio gástrico), ápices e bases pulmonares (murmúrio vesicular simétrico).',
          'Fixar tubo na comissura labial (~21 a 23 cm no adulto ou 3x o diâmetro interno do tubo).',
          'Conectar à ventilação mecânica com parâmetros protetores (VC 6 mL/kg de peso predito).',
          'Iniciar sedoanalgesia contínua de manutenção imediatamente para evitar despertar em vigília sob paralisia residual.'
        ]
      }
    ];

    return {
      pesoKg: pesoKg,
      indiceChoque: indiceChoque ? +indiceChoque.toFixed(2) : null,
      riscoColapsoHemodinamico: riscoColapsoHemodinamico,
      doseHipnotico: doseHipnotico,
      doseBnm: doseBnm,
      passosRsi: passosRsi,
      alertasCriticos: alertasCriticos
    };
  }

  /**
   * Seleciona o tamanho determinístico de Máscara Laríngea / Dispositivo Supraglótico por peso.
   * @param {number} pesoKg
   * @returns {Object}
   */
  function selecionarDispositivoSupraglotico(pesoKg) {
    pesoKg = Number(pesoKg) || 70;
    var tamanho = 4;
    var volumeCuffMaxMl = 30;
    var tuboMaxMm = 6.0;

    if (pesoKg < 5) {
      tamanho = 1;
      volumeCuffMaxMl = 4;
      tuboMaxMm = 3.5;
    } else if (pesoKg < 10) {
      tamanho = 1.5;
      volumeCuffMaxMl = 7;
      tuboMaxMm = 4.0;
    } else if (pesoKg < 20) {
      tamanho = 2;
      volumeCuffMaxMl = 10;
      tuboMaxMm = 4.5;
    } else if (pesoKg < 30) {
      tamanho = 2.5;
      volumeCuffMaxMl = 14;
      tuboMaxMm = 5.0;
    } else if (pesoKg < 50) {
      tamanho = 3;
      volumeCuffMaxMl = 20;
      tuboMaxMm = 6.0;
    } else if (pesoKg <= 70) {
      tamanho = 4;
      volumeCuffMaxMl = 30;
      tuboMaxMm = 6.5;
    } else {
      tamanho = 5;
      volumeCuffMaxMl = 40;
      tuboMaxMm = 7.0;
    }

    return {
      tamanho: tamanho,
      tipoRecomendado: 'Máscara Laríngea de 2ª Geração (ex: i-gel, ProSeal, Supreme com canal de drenagem gástrica)',
      volumeCuffMaxMl: volumeCuffMaxMl,
      observacaoCuff: 'No caso do dispositivo i-gel, não há cuff inflável (gel elastomérico anatômico sem necessidade de ar).',
      calibreTuboIntubacaoViaMascara: tuboMaxMm + ' mm'
    };
  }

  /**
   * Algoritmo determinístico ASA / DAS / Vortex para manejo de Via Aérea Difícil e CICO.
   * @param {Object} params
   * @returns {Object}
   */
  function algoritmoAsaViaAerea(params) {
    params = params || {};
    var tentativasLaringoscopia = Number(params.tentativasLaringoscopia) || 0;
    var sucessoIntubacao = params.sucessoIntubacao === true;
    var oxigenaComMascara = params.oxigenaComMascara !== false; // Default true a menos que falhe
    var dispositivoSupragloticoTentado = params.dispositivoSupragloticoTentado === true;
    var sucessoSupraglotico = params.sucessoSupraglotico === true;
    var pesoKg = Number(params.pesoKg) || 70;
    var cormackLehane = params.cormackLehane ? Number(params.cormackLehane) : null;

    var statusAtual = '';
    var planoAtivo = '';
    var acoesImediatas = [];
    var alertaVermelhoCico = false;
    var protocoloCricotireoidostomia = null;

    if (sucessoIntubacao) {
      statusAtual = 'SUCESSO NA INTUBAÇÃO OROTRAQUEAL';
      planoAtivo = 'MANUTENÇÃO E PÓS-INTUBAÇÃO';
      acoesImediatas = [
        'Confirmar posicionamento com Capnografia de onda imediata.',
        'Auscultar epigástrio e campos pleuropulmonares bilateralmente.',
        'Fixar o tubo no lábio em ~21 a 23 cm (ou 3x diâmetro interno do tubo).',
        'Iniciar sedoanalgesia contínua de manutenção.',
        'Solicitar radiografia de tórax no leito para checagem da ponta do tubo em relação à carina (alvo 3 a 5 cm acima).'
      ];
    } else if (tentativasLaringoscopia < 3) {
      statusAtual = 'INTUBAÇÃO EM ANDAMENTO (TENTATIVA ' + (tentativasLaringoscopia + 1) + ' DE 3)';
      planoAtivo = 'PLANO A: OTIMIZAÇÃO DA LARINGOSCOPIA';
      acoesImediatas = [
        'Trocar para Videolaringoscópio com lâmina hiperangulada (D-Blade) se disponível.',
        'Utilizar Bougie (introdutor elástico de Eschmann) como guia obrigatório.',
        'Otimizar posicionamento da cabeça (sniffing position ou elevação em rampa).',
        'Realizar manipulação laríngea externa: manobra BURP (Backwards, Upwards, Rightwards Pressure).',
        'Manter oxigenação apneica com cateter nasal a 15 L/min.',
        'ATENÇÃO: Limitar estritamente a no máximo 3 tentativas no total (idealmente a 2ª tentativa realizada pelo operador mais experiente).'
      ];
      if (cormackLehane === 3 || cormackLehane === 4) {
        acoesImediatas.push('Visão laringoscópica desfavorável (Cormack-Lehane ' + cormackLehane + '): O uso de videolaringoscopia com lâmina curva/hiperangulada e bougie é mandatório.');
      }
    } else {
      // 3 ou mais tentativas falharam: Falha do Plano A
      if (oxigenaComMascara && !dispositivoSupragloticoTentado) {
        statusAtual = 'FALHA DE INTUBAÇÃO (VIA AÉREA DIFÍCIL CONFIRMADA) - PACIENTE OXIGENA';
        planoAtivo = 'PLANO B: DISPOSITIVO SUPRAGLÓTICO (MÁSCARA LARÍNGEA)';
        var mlInfo = selecionarDispositivoSupraglotico(pesoKg);
        acoesImediatas = [
          'PARAR novas tentativas de laringoscopia direta para evitar sangramento e edema obstrutivo.',
          'Declarar à equipe em voz alta: "VIA AÉREA DIFÍCIL CONFIRMADA". Chamar ajuda adicional experiente.',
          'Inserir Dispositivo Supraglótico de 2ª geração: ' + mlInfo.tipoRecomendado + ' - Tamanho ' + mlInfo.tamanho + '.',
          'Checar ventilação, expansão torácica e capnografia através da máscara laríngea (máximo de 2 tentativas de inserção).',
          'Se ventilação adequada: estabilizar o paciente, passar sonda gástrica pelo canal de drenagem e planejar intubação definitiva com broncoscópio flexível através do dispositivo ou acordar o paciente.'
        ];
      } else if (dispositivoSupragloticoTentado && sucessoSupraglotico) {
        statusAtual = 'RESGATE COM DISPOSITIVO SUPRAGLÓTICO BEM-SUCEDIDO';
        planoAtivo = 'VENTILAÇÃO DE RESGATE ESTABILIZADA';
        acoesImediatas = [
          'Manter paciente ventilando via Máscara Laríngea com fração inspirada de O2 a 100%.',
          'Passar sonda nasogástrica/orogástrica pelo canal de alívio da ML para descompressão estomacal.',
          'Decisão estratégica definitiva:',
          ' • Opção 1: Intubação orotraqueal guiada por fibrobroncoscópio através da máscara laríngea.',
          ' • Opção 2: Se cirurgia eletiva e paciente sem risco crítico de aspiração, reverter bloqueador e acordar o paciente.',
          ' • Opção 3: Conduzir para traqueostomia eletiva se via aérea definitiva for imperativa a longo prazo.'
        ];
      } else {
        // NÃO INTUBA E NÃO OXIGENA (CICO)
        alertaVermelhoCico = true;
        statusAtual = 'EMERGÊNCIA CRÍTICA: NÃO INTUBA, NÃO OXIGENA (CICO - CANNOT INTUBATE, CANNOT OXYGENATE)';
        planoAtivo = 'PLANO D / eFONA: ACESSO CIRÚRGICO FRONTAL NO PESCOÇO IMEDIATO';
        acoesImediatas = [
          '🚨 ANUNCIAR EM VOZ ALTA PARA TODA A SALA: "EMERGÊNCIA DE VIA AÉREA: NÃO INTUBA, NÃO OXIGENA! INICIANDO ACESSO CIRÚRGICO FRONTAL IMEDIATO!"',
          '🚨 CHAMAR AJUDA IMEDIATA: Acionar cirurgião e suporte de emergência.',
          '🚨 Se o bloqueador neuromuscular utilizado foi o Rocurônio: administrar SUGAMADEX 16 mg/kg IV EM BOLUS RÁPIDO IMEDIATAMENTE (não atrasar a cricotireoidostomia).',
          '🚨 Manter tentativas de oxigenação com máscara a 4 mãos e O2 a 100% enquanto o acesso cirúrgico é executado sem qualquer hesitação.'
        ];

        protocoloCricotireoidostomia = {
          nome: 'Cricotireoidostomia Cirúrgica de Emergência (Técnica Bisturi-Bougie-Tubo / Scalpel-Bougie-Tube)',
          materiais: [
            'Bisturi de lâmina nº 10 ou 11',
            'Bougie (introdutor elástico traqueal de Eschmann)',
            'Tubo orotraqueal com cuff tamanho 6.0 mm',
            'Seringa de 10 mL com ar',
            'Gaze e clorexidina alcoólica'
          ],
          passoAPasso: [
            '1. Extensão cervical máxima (se não houver lesão medular confirmada com risco extremo).',
            '2. Laringe em pinça: com a mão não dominante, palpar a cartilagem tireóide, deslizar o dedo caudalmente até a depressão da membrana cricotireóidea (entre as cartilagens tireóidea e cricóidea).',
            '3. Incisão transversal única e firme de 1.5 a 2.0 cm através da pele e da membrana cricotireóidea com o bisturi nº 10.',
            '4. Rotação do bisturi: girar a lâmina em 90 graus na horizontal com o corte apontando caudalmente (em direção aos pés) para abrir o espaço.',
            '5. Inserir o Bougie através da incisão para o interior da traqueia (sentir os cliques dos anéis traqueais e a parada na carina).',
            '6. Deslizar o Tubo 6.0 mm com cuff sobre o Bougie para dentro da traqueia até o cuff desaparecer.',
            '7. Retirar o Bougie mantendo o tubo firme.',
            '8. Insuflar o cuff imediatamente com 5 a 10 mL de ar.',
            '9. Conectar ao circuito ventilatório, confirmar expansão torácica e capnografia em onda, e fixar com cadarço.'
          ],
          contraindicacoesAvisos: [
            'NÃO tentar punção com agulha fina (Jelco 14) em adultos: tem alta taxa de falha, acotovelamento e não permite ventilação adequada.',
            'A técnica bisturi-bougie-tubo é a técnica padrão-ouro da DAS (Difficult Airway Society) para cricotireoidostomia de resgate em adultos.'
          ]
        };
      }
    }

    return {
      statusAtual: statusAtual,
      planoAtivo: planoAtivo,
      alertaVermelhoCico: alertaVermelhoCico,
      acoesImediatas: acoesImediatas,
      protocoloCricotireoidostomia: protocoloCricotireoidostomia
    };
  }

  /**
   * Formata relatório visual de via aérea para o Cockpit ou Telegram.
   * @param {Object} dados
   * @returns {string}
   */
  function formatarResumoViaAerea(dados) {
    dados = dados || {};
    var out = [];
    out.push("=== MANEJO DETERMINÍSTICO DE VIA AÉREA DIFÍCIL (ASA / DAS) ===");

    if (dados.lemon) {
      out.push("\n[PREDIÇÃO LEMON]: " + dados.lemon.classificacao + " (" + dados.lemon.pontos + " pontos)");
      if (dados.lemon.achados && dados.lemon.achados.length > 0) {
        dados.lemon.achados.forEach(function(a) {
          out.push(" • " + a.criterio + ": " + a.detalhe);
        });
      }
    }

    if (dados.rsi) {
      out.push("\n[SEQUÊNCIA RÁPIDA DE INTUBAÇÃO - RSI (7 Ps)]");
      if (dados.rsi.riscoColapsoHemodinamico) {
        out.push("⚠️ ALERTA: Alto risco de colapso circulatório! Ressuscitação hemodinâmica antes da indução.");
      }
      out.push(" • Hipnótico: " + dados.rsi.doseHipnotico.farmaco + " -> " + dados.rsi.doseHipnotico.posologia);
      out.push(" • Bloqueador: " + dados.rsi.doseBnm.farmaco + " -> " + dados.rsi.doseBnm.posologia);
      if (dados.rsi.doseBnm.antidotoResgate) {
        out.push(" • Antídoto/Resgate: " + dados.rsi.doseBnm.antidotoResgate);
      }
    }

    if (dados.algoritmo) {
      out.push("\n[ALGORITMO ASA / DAS]");
      out.push("Plano: " + dados.algoritmo.planoAtivo);
      out.push("Status: " + dados.algoritmo.statusAtual);
      if (dados.algoritmo.alertaVermelhoCico) {
        out.push("\n🚨 EMERGÊNCIA CICO ATIVADA: ACESSO CIRÚRGICO FRONTAL NO PESCOÇO IMEDIATO!");
      }
    }

    return out.join("\n");
  }

  return {
    avaliarLemon: avaliarLemon,
    avaliarVentilacaoMascara: avaliarVentilacaoMascara,
    calcularRsi: calcularRsi,
    selecionarDispositivoSupraglotico: selecionarDispositivoSupraglotico,
    algoritmoAsaViaAerea: algoritmoAsaViaAerea,
    formatarResumoViaAerea: formatarResumoViaAerea
  };
})();

if (typeof module !== 'undefined' && module.exports) {
  module.exports = ViaAereaDificilService;
}


